import type { Node, RootContent, TopLevelContent } from "mdast";
import type { BlockStructure } from "../block/scanner.ts";
import type { InlineProfile } from "../inline/profile.ts";
import type { InlineRegionCursor } from "../inline/region.ts";
import type { SourceLocator, SourcePosition } from "../source-view.ts";
import type { InlineBuildContext } from "./inline.ts";

export interface BlockBuildContext {
  // Inline regions build serially, so this context can be rebound for each region.
  inlineContext: InlineBuildContext | undefined;
  cursor: InlineRegionCursor | undefined;
  locator: SourceLocator;
  structure: BlockStructure;
  profile: InlineProfile;
  source: string;
}

// Core owns build traversal; profiles supply every syntax-specific node builder.
export type BlockNodeBuilder<T extends object = Node> = (
  tokenStart: number,
  context: BlockBuildContext,
) => T;

export function leafBlockPosition(
  tokenStart: number,
  context: BlockBuildContext,
): SourcePosition {
  const tokens = context.structure.tokens;
  return context.locator.positionAt(
    tokens.start(tokenStart),
    tokens.contentEnd(context.source, tokenStart),
  );
}

export function buildBlockNode<T extends object = TopLevelContent>(
  tokenStart: number,
  context: BlockBuildContext,
): T {
  const kind = context.structure.tokens.kind(tokenStart);
  return context.structure.builds[kind]!(tokenStart, context) as T;
}

export function buildBlockChildren<T extends object = RootContent>(
  tokenStart: number,
  context: BlockBuildContext,
): T[] {
  const builds = context.structure.builds;
  const tokens = context.structure.tokens;
  const children: T[] = [];
  const tokenEnd = tokenStart + tokens.nodeLength(tokenStart) - 1;
  for (let child = tokenStart + 1; child < tokenEnd;) {
    const length = tokens.nodeLength(child);
    if (length > 0) {
      const build = builds[tokens.kind(child)];
      if (build) {
        children.push(build(child, context) as T);
      }
    }
    child += length || 1;
  }
  return children;
}

import type { PhrasingContent, Text } from "mdast";
import { trimLineWhitespaceEnd } from "../block/lines.ts";
import { BlockKind } from "../constants/block.ts";
import { InlineKind, InlineRole } from "../constants/inline.ts";
import {
  inlineTokenCount,
  inlineTokenEnd,
  inlineTokenKind,
  inlineTokenStart,
  type InlineTokenStream,
} from "../inline/tokens.ts";
import {
  type SourceLocator,
  type SourcePosition,
  type SourceSpan,
  SourceView,
} from "../source-view.ts";
import type { InlineProfile } from "../inline/profile.ts";
import type { BlockBuildContext } from "./block.ts";

type InlineNonText = Exclude<PhrasingContent, Text>;

export interface InlineBuildContext {
  builders: InlineProfile["builders"];
  // Recursive builders publish the next token here; a child range stops at its closer.
  tokenIndex: number;
  locator: SourceLocator;
  // Table splitting preserves `\|`; inline code removes that structural escape.
  tableCell: boolean;
  tokens: InlineTokenStream;
  view: SourceView;
}

export interface InlineFragment {
  children: PhrasingContent[];
}

interface InlineOutput extends InlineFragment {
  // The cursor bounds source text that remains implicit between semantic tokens.
  cursor: number;
  // The text child is published immediately; only its source end remains pending.
  pendingText: Text | undefined;
  // Keep the end in view coordinates until the merged text is complete.
  pendingEnd: number;
  // Keep only the consecutive literal suffix; decoded whitespace is semantic text.
  pendingLiteral: string;
}

export type InlineLeafBuilder = (
  tokenIndex: number,
  position: SourcePosition,
  context: InlineBuildContext,
) => InlineNonText;

export type InlineTextBuilder = (
  tokenIndex: number,
  context: InlineBuildContext,
) => string;

export type InlinePairBuilder = (
  openToken: number,
  closeToken: number,
  position: SourcePosition,
  children: PhrasingContent[],
  context: InlineBuildContext,
) => InlineNonText;

export type InlineTokenDecorator = (
  tokenIndex: number,
  sourceSpan: SourceSpan,
  context: InlineBuildContext,
  target: InlineFragment,
) => boolean;

export type InlineBuilder =
  | InlineLeafBuilder
  | InlinePairBuilder
  | InlineTextBuilder
  | InlineTokenDecorator;

function appendText(
  context: InlineBuildContext,
  output: InlineOutput,
  value: string,
  start: number,
  end: number,
  literal: boolean,
): void {
  if (output.pendingText === void 0 || "attributes" in output.pendingText) {
    const startLocation = context.locator.locationAt(context.view.mapOffset(start));
    const text: Text = {
      type: "text",
      value,
      position: { start: startLocation, end: startLocation },
    };
    output.children.push(text);
    output.pendingText = text;
    output.pendingLiteral = literal ? value : "";
  }
  else {
    output.pendingText.value += value;
    output.pendingLiteral = literal ? output.pendingLiteral + value : "";
  }
  output.pendingEnd = end;
}

function finishText(context: InlineBuildContext, output: InlineOutput): void {
  if (output.pendingText) {
    output.pendingText.position!.end = context.locator.locationAt(
      context.view.mapEnd(output.pendingEnd),
    );
  }
}

function trimTrailingText(context: InlineBuildContext, output: InlineOutput): void {
  if (output.pendingText) {
    const literal = output.pendingLiteral;
    const removed = literal.length - trimLineWhitespaceEnd(literal, 0, literal.length);
    if (removed > 0) {
      // Removing an all-whitespace pending gap must also move its source start.
      if (removed === output.pendingText.value.length) {
        output.pendingText.position!.start = context.locator.locationAt(
          context.view.mapOffset(output.pendingEnd),
        );
      }
      output.pendingText.value = output.pendingText.value.slice(0, -removed);
      output.pendingEnd -= removed;
      output.pendingLiteral = "";
    }
  }
}

function appendGap(
  context: InlineBuildContext,
  output: InlineOutput,
  start: number,
  end: number,
): void {
  const value = context.view.text.slice(start, end);
  appendText(context, output, value, start, end, true);
}

// Resolution has already made semantic pairs unambiguous, so projection can consume that stream
// directly instead of copying it into a second syntax arena.
function appendRange(context: InlineBuildContext, output: InlineOutput, trimEnd: boolean): void {
  let index = context.tokenIndex;
  const end = inlineTokenCount(context.tokens);
  while (index < end) {
    const kind = inlineTokenKind(context.tokens, index);
    // Newline has fixed semantic text, so it does not enter profile builder dispatch.
    if (kind === InlineKind.Newline) {
      const endingStart = inlineTokenStart(context.tokens, index);
      const contentStart = inlineTokenEnd(context.tokens, index);
      if (endingStart > output.cursor) {
        appendGap(context, output, output.cursor, endingStart);
      }
      trimTrailingText(context, output);
      appendText(context, output, "\n", endingStart, contentStart, false);
      output.cursor = contentStart;
      index++;
      continue;
    }
    const childStart = inlineTokenStart(context.tokens, index);
    if (kind < InlineRole.Leaf) {
      const childEnd = inlineTokenEnd(context.tokens, index);
      if (childStart > output.cursor) {
        appendGap(context, output, output.cursor, childStart);
      }
      const build = context.builders[kind] as InlineTextBuilder;
      appendText(context, output, build(index, context), childStart, childEnd, kind === InlineKind.LiteralText);
      output.cursor = childEnd;
      index++;
      continue;
    }
    if (kind < InlineRole.Decorate) {
      if (kind >= InlineRole.Pair && kind & 1) {
        break;
      }
      if (childStart > output.cursor) {
        appendGap(context, output, output.cursor, childStart);
      }
      finishText(context, output);
      output.children.push(buildNode(context, index, kind));
      output.pendingText = void 0;
      index = context.tokenIndex;
      output.cursor = inlineTokenEnd(context.tokens, index - 1);
      continue;
    }
    const childEnd = inlineTokenEnd(context.tokens, index);
    finishText(context, output);
    const sourceStart = context.view.mapOffset(childStart);
    const sourceSpan = {
      start: sourceStart,
      end: childStart === childEnd ? sourceStart : context.view.mapEnd(childEnd),
    };
    const decorate = context.builders[kind] as InlineTokenDecorator;
    if (decorate(index, sourceSpan, context, output)) {
      // Applied decorators may mutate the exposed child list, so refresh the cached projection.
      const previous = output.children.at(-1);
      output.pendingText = previous?.type === "text" ? previous as Text : void 0;
      output.pendingEnd = childEnd;
      output.cursor = childEnd;
    }
    index++;
  }
  const contentEnd = index < end ? inlineTokenStart(context.tokens, index) : context.view.text.length;
  if (contentEnd > output.cursor) {
    appendGap(context, output, output.cursor, contentEnd);
  }
  // Every range closes its own projection; only a fragment boundary owns final trimming.
  if (trimEnd) {
    trimTrailingText(context, output);
    if (output.pendingText && !output.pendingText.value) {
      output.children.pop();
    }
  }
  finishText(context, output);
  context.tokenIndex = index;
}

function buildLiteral(context: InlineBuildContext, start: number, end: number): PhrasingContent[] {
  return start >= end
    ? []
    : [{
      type: "text",
      value: context.view.text.slice(start, end),
      position: context.locator.positionAt(
        context.view.mapOffset(start),
        context.view.mapEnd(end),
      ),
    }];
}

function buildNode(context: InlineBuildContext, token: number, kind: number): InlineNonText {
  const startOffset = inlineTokenStart(context.tokens, token);
  const sourceStart = context.view.mapOffset(startOffset);
  const start = context.locator.locationAt(sourceStart);
  let close = token;
  let children: PhrasingContent[] | undefined;
  if (kind >= InlineRole.Pair) {
    const next = token + 1;
    const contentStart = inlineTokenEnd(context.tokens, token);
    if (inlineTokenKind(context.tokens, next) === kind + 1) {
      close = next;
      children = buildLiteral(context, contentStart, inlineTokenStart(context.tokens, close));
    }
    else {
      context.tokenIndex = next;
      children = buildFragment(context, contentStart, kind + 1).children;
      close = context.tokenIndex;
    }
  }
  context.tokenIndex = close + 1;
  const endOffset = inlineTokenEnd(context.tokens, close);
  const position = {
    start,
    end: context.locator.locationAt(
      startOffset === endOffset ? sourceStart : context.view.mapEnd(endOffset),
    ),
  };
  const build = context.builders[kind];
  return children
    ? (build as InlinePairBuilder)(token, close, position, children, context)
    : (build as InlineLeafBuilder)(token, position, context);
}

function buildFragment(context: InlineBuildContext, cursor: number, closeKind: number): InlineFragment {
  const trimEnd = closeKind === InlineKind.None;
  const token = context.tokenIndex;
  const kind = inlineTokenKind(context.tokens, token);
  let children: PhrasingContent[] | undefined;
  if (
    kind >= InlineRole.Leaf &&
    kind < InlineRole.Decorate &&
    inlineTokenStart(context.tokens, token) === cursor
  ) {
    const node = buildNode(context, token, kind);
    const atEnd = context.tokenIndex === inlineTokenCount(context.tokens);
    cursor = inlineTokenEnd(context.tokens, context.tokenIndex - 1);
    if (atEnd || inlineTokenKind(context.tokens, context.tokenIndex) === closeKind) {
      const end = atEnd ? context.view.text.length : inlineTokenStart(context.tokens, context.tokenIndex);
      if (
        cursor === end ||
        trimEnd && cursor === trimLineWhitespaceEnd(context.view.text, cursor, end)
      ) {
        return { children: [node] };
      }
    }
    children = [node];
  }
  const output = {
    children: children ?? [],
    cursor,
    pendingText: void 0,
    pendingEnd: 0,
    pendingLiteral: "",
  };
  appendRange(context, output, trimEnd);
  return output;
}

export function buildInlineFragment(
  tokenStart: number,
  tableCell: boolean,
  context: BlockBuildContext,
): InlineFragment {
  let tokens: InlineTokenStream;
  let view: SourceView;

  if (context.cursor) {
    const region = context.cursor.take(tokenStart);
    if (!region) {
      return { children: [] };
    }
    tokens = region.tokens;
    view = region.view;
  }
  else {
    const blockTokens = context.structure.tokens;
    const nodeLength = blockTokens.nodeLength(tokenStart);
    if (nodeLength <= 1 || blockTokens.kind(tokenStart + 1) !== BlockKind.InlineChunk) {
      return { children: [] };
    }

    const previousView = context.inlineContext?.view;
    view = (
      previousView?.reset(context.source, blockTokens, tokenStart, nodeLength),
      previousView
    ) ?? new SourceView(context.source, blockTokens, tokenStart, nodeLength);

    tokens = context.profile.tokenize(view.text, view.withBoundaryBreak);
    if (tokens.length) {
      tokens = context.profile.resolve(view.text, tokens, blockTokens);
    }
  }

  const inlineContext = context.inlineContext ??= {
    builders: context.profile.builders,
    tokenIndex: 0,
    locator: context.locator,
    tableCell,
    tokens,
    view,
  };
  inlineContext.tableCell = tableCell;
  inlineContext.tokens = tokens;
  inlineContext.view = view;

  if (tokens.length === 0) {
    const end = trimLineWhitespaceEnd(view.text, 0, view.text.length);
    return {
      children: buildLiteral(inlineContext, 0, end),
    };
  }
  inlineContext.tokenIndex = 0;
  return buildFragment(inlineContext, 0, InlineKind.None);
}

import { Character } from "../constants/character.ts";
import { InlineKind, InlineRole } from "../constants/inline.ts";
import {
  appendResolvedRawToken,
  compileDelimiterConfigs,
  type DelimiterConfig,
  type DelimiterReplacement,
  type DelimiterRun,
  delimiterRunAt,
  resolveDelimiterScope,
} from "../inline/delimiter.ts";
import {
  appendInlineToken,
  inlineTokenCount,
  inlineTokenData,
  inlineTokenEnd,
  InlineTokenField,
  inlineTokenKind,
  inlineTokenStart,
  type InlineTokenStream,
} from "../inline/tokens.ts";
import { emptyArray } from "../primitives.ts";
import { attributesEnd } from "./features/attributes/shared.ts";
import { footnoteLabelAt } from "./features/footnote/shared.ts";
import { isMarkdownWhitespace, normalizeIdentifier } from "./utils.ts";
import type { DefinitionLookup } from "../block/tokens.ts";

interface InlineResolverOptions {
  component: boolean;
  footnote: boolean;
}

export type InlineResolver = (
  source: string,
  tokens: InlineTokenStream,
  definitions: DefinitionLookup,
) => InlineTokenStream;

export type InlineResolverFactory = (delimiters: readonly DelimiterConfig[]) => InlineResolver;

interface BracketFrame {
  open: number;
  // Enclosing bracket in the token stream.
  parent: BracketFrame | undefined;
  // Next opener in source order.
  next: BracketFrame | undefined;
  state: number;
  candidateStart: number;
  // Last delimiter before this bracket's content.
  delimiterBottom: DelimiterRun | undefined;
  // Previous opener in the link-matching stack.
  logicalParent: BracketFrame | undefined;
  // Output for the opener; None skips its source tokens.
  openingKind: InlineKind;
  openingEnd: number;
  // The raw closer may finish a different frame's link.
  closingKind: InlineKind;
  closingEnd: number;
}

const enum FrameState {
  // Analysis sets this together with openingKind; ordinary link matches leave it unset.
  Claimed = 1,
  BareSpan = 2,
  Image = 8,
  InLinkLabel = 16,
}

// A link tail cancels bare spans but keeps components and spans with attributes.
function rewriteLinkCandidates(candidates: BracketFrame[], start: number): void {
  let write = start;
  for (let index = start; index < candidates.length; index++) {
    const candidate = candidates[index];
    if (candidate.state & FrameState.BareSpan) {
      // Bare spans come from `[`. Analysis has not changed their boundary offsets.
      candidate.state = 0;
      candidate.openingKind = InlineKind.BracketOpen;
    }
    else {
      candidate.state |= FrameState.InLinkLabel;
      candidates[write++] = candidate;
    }
  }
  candidates.length = write;
}

function referenceLabelEnd(source: string, start: number): number {
  if (source.charCodeAt(start) !== Character.LeftSquareBracket) {
    return -1;
  }
  let offset = start + 1;
  if (source.charCodeAt(offset) === Character.RightSquareBracket) {
    return offset + 1;
  }
  let characters = 0;
  let hasContent = false;
  while (offset < source.length && characters < 999) {
    const code = source.charCodeAt(offset);
    if (code === Character.RightSquareBracket) {
      return hasContent ? offset + 1 : -1;
    }
    if (code === Character.LeftSquareBracket) {
      return -1;
    }
    if (code === Character.ReverseSolidus) {
      if (offset + 1 >= source.length) {
        return -1;
      }
      hasContent = true;
      offset += 2;
    }
    else {
      hasContent ||= !isMarkdownWhitespace(code);
      offset++;
    }
    characters++;
  }
  return -1;
}

function acceptsShortcutLabel(source: string, start: number, end: number): boolean {
  let hasContent = false;
  let characters = 0;
  for (let offset = start; offset < end; offset++) {
    const code = source.charCodeAt(offset);
    hasContent ||= !isMarkdownWhitespace(code);
    if (
      code >= Character.HighSurrogateStart &&
      code <= Character.HighSurrogateEnd &&
      offset + 1 < end
    ) {
      const trailing = source.charCodeAt(offset + 1);
      if (trailing >= Character.LowSurrogateStart && trailing <= Character.LowSurrogateEnd) {
        offset++;
      }
    }
    if (++characters > 999) {
      return false;
    }
  }
  return hasContent;
}

function analyzeBrackets(
  source: string,
  tokens: InlineTokenStream,
  definitions: DefinitionLookup,
  options: InlineResolverOptions,
  start: number,
  end: number,
): BracketFrame | undefined {
  let first: BracketFrame | undefined;
  let last: BracketFrame | undefined;
  let candidates: BracketFrame[] | undefined;
  let stackTop: BracketFrame | undefined;
  for (let tokenIndex = start; tokenIndex < end; tokenIndex++) {
    const kind = inlineTokenKind(tokens, tokenIndex);
    if (kind >= InlineKind.ImageOpen && kind <= InlineKind.BracketOpen) {
      const frame: BracketFrame = {
        open: tokenIndex,
        parent: stackTop,
        next: void 0,
        state: kind === InlineKind.ImageOpen ? FrameState.Image : 0,
        candidateStart: candidates?.length ?? 0,
        delimiterBottom: void 0,
        logicalParent: void 0,
        openingKind: kind,
        openingEnd: inlineTokenEnd(tokens, tokenIndex),
        closingKind: InlineKind.None,
        closingEnd: 0,
      };
      if (last) {
        last.next = frame;
      }
      else {
        first = frame;
      }
      last = frame;
      stackTop = frame;
      continue;
    }
    if (kind !== InlineKind.LinkTail && kind !== InlineKind.BracketClose) {
      continue;
    }

    if (!stackTop) {
      continue;
    }
    const frame = stackTop;
    stackTop = frame.parent;
    frame.closingKind = kind;
    frame.closingEnd = inlineTokenEnd(tokens, tokenIndex);
    const image = frame.state & FrameState.Image;
    const openToken = frame.open;

    if (options.footnote && kind === InlineKind.BracketClose) {
      const labelStart = inlineTokenStart(tokens, openToken) + (image ? 1 : 0);
      const label = footnoteLabelAt(source, labelStart, source.length);
      if (
        label?.end === frame.closingEnd &&
        definitions.hasDefinition(label.definitionKey)
      ) {
        frame.state = FrameState.Claimed;
        frame.openingKind = InlineKind.FootnoteReference;
        frame.openingEnd = frame.closingEnd;
        if (candidates) {
          candidates.length = frame.candidateStart;
        }
        continue;
      }
    }

    if (!options.component || image) {
      continue;
    }
    if (kind === InlineKind.LinkTail && candidates) {
      rewriteLinkCandidates(candidates, frame.candidateStart);
    }
    const componentToken = openToken - 1;
    if (
      componentToken >= 0 &&
      inlineTokenKind(tokens, componentToken) === InlineKind.InlineComponent &&
      inlineTokenEnd(tokens, componentToken) === inlineTokenStart(tokens, openToken)
    ) {
      frame.state = FrameState.Claimed;
      frame.openingKind = InlineKind.InlineComponentOpen;
    }
    else {
      const suffixStart = inlineTokenStart(tokens, tokenIndex) + 1;
      const trailing = source.charCodeAt(suffixStart);
      if (
        trailing === Character.LeftParenthesis ||
        trailing === Character.LeftSquareBracket
      ) {
        continue;
      }
      const attributed = (
        trailing === Character.LeftCurlyBracket && attributesEnd(source, suffixStart) !== void 0
      );
      frame.state = FrameState.Claimed | (attributed ? 0 : FrameState.BareSpan);
      frame.openingKind = InlineKind.InlineSpanOpen;
    }
    // Only nested labels need to be revisited when a link tail appears.
    if (stackTop) {
      candidates ??= [];
      candidates.push(frame);
    }
  }
  return first;
}

function consumeFrame(frame: BracketFrame, end: number): void {
  frame.state = 0;
  frame.openingKind = InlineKind.None;
  frame.openingEnd = end;
}

function resolvePairedSyntax(
  source: string,
  tokens: InlineTokenStream,
  nextFrame: BracketFrame | undefined,
  definitions: DefinitionLookup,
  delimiterByKind: ReturnType<typeof compileDelimiterConfigs>,
  start: number,
  end: number,
): readonly DelimiterReplacement[][] {
  // Reference links need definitions; inline link tails are already validated.
  const hasDefinitions = nextFrame !== void 0 && definitions.hasDefinitions();
  let firstRun: DelimiterRun | undefined;
  let lastRun: DelimiterRun | undefined;
  let replacements: DelimiterReplacement[][] | undefined;
  let rawTop: BracketFrame | undefined;
  let logicalTop: BracketFrame | undefined;
  let consumedEnd = -1;
  let consumeFrames = false;
  let inactiveBefore = 0;
  let lastVisibleOpener = -1;
  let literalDepth = 0;

  for (let tokenIndex = start; tokenIndex < end; tokenIndex++) {
    const kind = inlineTokenKind(tokens, tokenIndex);
    const tokenStart = inlineTokenStart(tokens, tokenIndex);
    if (consumedEnd >= 0 && tokenStart >= consumedEnd) {
      consumedEnd = -1;
      consumeFrames = false;
    }
    const consuming = consumedEnd >= 0;

    const delimiter = delimiterByKind[kind];
    if (!consuming && delimiter) {
      const run = delimiterRunAt(source, tokens, tokenIndex, delimiter);
      if (run) {
        run.previous = lastRun;
        if (lastRun) {
          lastRun.next = run;
        }
        else {
          firstRun = run;
        }
        lastRun = run;
      }
    }

    if (kind >= InlineKind.ImageOpen && kind <= InlineKind.BracketOpen) {
      const frame = nextFrame!;
      nextFrame = frame.next;
      rawTop = frame;
      if (consuming) {
        if (consumeFrames) {
          consumeFrame(frame, consumedEnd);
        }
        continue;
      }
      frame.delimiterBottom = lastRun;

      const state = frame.state;
      if (state & FrameState.Claimed) {
        if (frame.openingKind === InlineKind.FootnoteReference) {
          consumedEnd = frame.openingEnd;
        }
        else if (state & FrameState.InLinkLabel) {
          literalDepth++;
        }
        continue;
      }
      const image = kind === InlineKind.ImageOpen;
      if (literalDepth > 0 && !image) {
        frame.openingKind = InlineKind.None;
        frame.closingKind = InlineKind.None;
        continue;
      }
      frame.logicalParent = logicalTop;
      logicalTop = frame;
      lastVisibleOpener = tokenIndex;
      continue;
    }

    if (kind !== InlineKind.LinkTail && kind !== InlineKind.BracketClose) {
      continue;
    }
    const rawFrame = rawTop;
    if (rawFrame !== void 0) {
      rawTop = rawFrame.parent;
    }
    if (consuming) {
      if (consumeFrames && rawFrame !== void 0) {
        consumeFrame(rawFrame, inlineTokenEnd(tokens, tokenIndex));
      }
      continue;
    }

    const rawState = rawFrame?.state ?? 0;
    let scopeFrame: BracketFrame | undefined;
    // Footnotes consume their closing bracket, which was skipped above.
    // Only component and span claims reach this branch.
    if (rawState & FrameState.Claimed) {
      const frame = scopeFrame = rawFrame!;
      if (frame.openingKind !== InlineKind.InlineComponentOpen || inlineTokenEnd(tokens, frame.open) < tokenStart) {
        frame.closingKind = frame.openingKind + 1;
      }
      else {
        frame.openingKind = InlineKind.None;
        frame.closingKind = InlineKind.None;
      }
      frame.closingEnd = tokenStart + 1;
    }
    else if (literalDepth <= 0 || rawFrame === void 0 || rawState & FrameState.Image) {
      const frame = logicalTop;
      if (frame !== void 0) {
        logicalTop = frame.logicalParent;
      }
      if (frame !== void 0 && (kind === InlineKind.LinkTail || hasDefinitions)) {
        const openToken = frame.open;
        const image = frame.state & FrameState.Image;
        // An inner link prevents outer links from matching; images remain allowed.
        if (image || openToken + 1 >= inactiveBefore) {
          const tokenEnd = inlineTokenEnd(tokens, tokenIndex);
          let closeEnd = tokenEnd;
          let openingKind = kind === InlineKind.LinkTail ? InlineKind.LinkOpen : InlineKind.None;
          if (!openingKind) {
            const contentStart = inlineTokenEnd(tokens, openToken);
            const contentEnd = tokenStart;
            const labelEnd = referenceLabelEnd(source, closeEnd);
            if (labelEnd > 0) {
              const explicit = source.slice(closeEnd + 1, labelEnd - 1);
              const label = explicit || source.slice(contentStart, contentEnd);
              if (definitions.hasDefinition(normalizeIdentifier(label))) {
                openingKind = InlineKind.ReferenceOpen;
                closeEnd = labelEnd;
              }
            }
            else if (
              lastVisibleOpener <= openToken &&
              acceptsShortcutLabel(source, contentStart, contentEnd) &&
              definitions.hasDefinition(normalizeIdentifier(source.slice(contentStart, contentEnd)))
            ) {
              openingKind = InlineKind.ReferenceOpen;
            }
          }

          if (openingKind) {
            openingKind += image ? 2 : 0;
            frame.openingKind = openingKind;
            rawFrame!.closingKind = openingKind + 1;
            rawFrame!.closingEnd = closeEnd;
            scopeFrame = frame;
            if (!image) {
              inactiveBefore = openToken + 1;
            }
            if (closeEnd > tokenEnd) {
              consumedEnd = closeEnd;
              consumeFrames = true;
            }
          }
        }
      }
    }

    if (rawState & FrameState.InLinkLabel) {
      literalDepth--;
    }
    // Resolve only the delimiters inside this label.
    if (scopeFrame && lastRun !== scopeFrame.delimiterBottom) {
      const bottom = scopeFrame.delimiterBottom;
      const first = bottom ? bottom.next! : firstRun!;
      if (bottom) {
        bottom.next = void 0;
      }
      else {
        firstRun = void 0;
      }
      first.previous = void 0;
      replacements = resolveDelimiterScope(first, replacements);
      lastRun = bottom;
    }
  }
  if (firstRun) {
    replacements = resolveDelimiterScope(firstRun, replacements);
  }
  return replacements ?? emptyArray;
}

function emitResolvedTokens(
  tokens: InlineTokenStream,
  nextFrame: BracketFrame | undefined,
  replacements: readonly DelimiterReplacement[][],
  start: number,
  end: number,
): InlineTokenStream {
  const result = start ? tokens.slice(0, start * InlineTokenField.Stride) : [];
  let rawTop: BracketFrame | undefined;
  let skipEnd = -1;
  for (let index = start; index < end; index++) {
    const kind = inlineTokenKind(tokens, index);
    const tokenStart = inlineTokenStart(tokens, index);
    let outputKind = kind;
    let outputEnd = inlineTokenEnd(tokens, index);
    if (kind >= InlineKind.ImageOpen && kind <= InlineKind.BracketOpen) {
      const frame = nextFrame!;
      nextFrame = frame.next;
      rawTop = frame;
      outputKind = frame.openingKind;
      outputEnd = frame.openingEnd;
    }
    else if (kind === InlineKind.LinkTail || kind === InlineKind.BracketClose) {
      const frame = rawTop;
      rawTop = frame?.parent;
      if (frame) {
        outputKind = frame.closingKind;
        outputEnd = frame.closingEnd;
      }
    }
    // Even skipped tokens must update the raw bracket stack.
    if (tokenStart < skipEnd) {
      continue;
    }
    if (outputKind === InlineKind.InlineComponentOpen) {
      // Use the preceding component token as the label's opener.
      const field = result.length - InlineTokenField.Stride;
      result[field | InlineTokenField.Kind] = outputKind;
      result[field | InlineTokenField.End] = outputEnd;
    }
    else if (outputKind >= InlineRole.Text) {
      const sourceStart = tokenStart + (
        outputKind === InlineKind.FootnoteReference && kind === InlineKind.ImageOpen ? 1 : 0
      );
      appendInlineToken(result, outputKind, sourceStart, outputEnd, inlineTokenData(tokens, index));
      skipEnd = outputEnd;
    }
    else if (outputKind === InlineKind.None) {
      skipEnd = outputEnd;
    }
    else {
      appendResolvedRawToken(result, tokens, index, replacements);
    }
  }
  return result;
}

export function compileInlineResolver(options: InlineResolverOptions): InlineResolverFactory {
  return (delimiterConfigs) => {
    const delimiterByKind = compileDelimiterConfigs(delimiterConfigs);
    return (source, tokens, definitions) => {
      // Start matching at the first raw token; the emitter copies the prefix.
      let start = 0;
      const end = inlineTokenCount(tokens);
      while (start < end && inlineTokenKind(tokens, start) >= InlineRole.Text) {
        start++;
      }
      if (start === end) {
        return tokens;
      }
      // A single opener followed by a validated link tail needs no bracket analysis.
      if (start === 0 && end === 2 && inlineTokenKind(tokens, 1) === InlineKind.LinkTail) {
        const opener = inlineTokenKind(tokens, 0);
        if (opener === InlineKind.BracketOpen || opener === InlineKind.ImageOpen) {
          const kind = opener === InlineKind.ImageOpen ? InlineKind.ImageLinkOpen : InlineKind.LinkOpen;
          const result = tokens.slice();
          result[InlineTokenField.Kind] = kind;
          result[InlineTokenField.Stride | InlineTokenField.Kind] = kind + 1;
          return result;
        }
      }
      const frames = analyzeBrackets(source, tokens, definitions, options, start, end);
      const replacements = resolvePairedSyntax(source, tokens, frames, definitions, delimiterByKind, start, end);
      return emitResolvedTokens(tokens, frames, replacements, start, end);
    };
  };
}

