import type { PhrasingContent } from "mdast";
import { Character } from "../../constants/character.ts";
import { InlineKind } from "../../constants/inline.ts";
import {
  appendInlineToken,
  inlineTokenData,
  inlineTokenEnd,
  inlineTokenStart,
  inlineTokenText,
} from "../../inline/tokens.ts";
import { isMarkdownWhitespace, normalizeIdentifier, semanticText } from "../utils.ts";
import { buildDecodedInlineText } from "./text.ts";
import type { InlinePairBuilder } from "../../fragment/inline.ts";
import type { SyntaxFeature } from "../types.ts";

function skipWhitespace(source: string, start: number, end = source.length): number {
  while (start < end) {
    const code = source.charCodeAt(start);
    if (!isMarkdownWhitespace(code)) {
      break;
    }
    start++;
  }
  return start;
}

function linkDestinationEnd(source: string, start: number): number {
  if (source.charCodeAt(start) === Character.LessThanSign) {
    let end = start + 1;
    while (end < source.length) {
      const code = source.charCodeAt(end);
      if (code === Character.GreaterThanSign) {
        return end + 1;
      }
      if (
        code === Character.LineFeed ||
        code === Character.CarriageReturn ||
        code === Character.LessThanSign
      ) {
        return -1;
      }
      end += code === Character.ReverseSolidus && end + 1 < source.length ? 2 : 1;
    }
    return -1;
  }

  let depth = 0;
  let end = start;
  let consumed = false;
  while (end < source.length) {
    const code = source.charCodeAt(end);
    if (code === Character.ReverseSolidus) {
      if (end + 1 >= source.length) {
        break;
      }
      consumed = true;
      end += 2;
      continue;
    }
    if (code === Character.LeftParenthesis) {
      if (depth === 32) {
        return -1;
      }
      depth++;
      consumed = true;
      end++;
      continue;
    }
    if (code === Character.RightParenthesis) {
      if (depth === 0) {
        break;
      }
      depth--;
      consumed = true;
      end++;
      continue;
    }
    if (isMarkdownWhitespace(code)) {
      break;
    }
    consumed = true;
    end++;
  }
  return consumed && depth === 0 ? end : -1;
}

function linkTitleEnd(source: string, start: number): number {
  const marker = source.charCodeAt(start);
  const close = marker === Character.LeftParenthesis ? Character.RightParenthesis : marker;
  if (
    marker !== Character.QuotationMark &&
    marker !== Character.Apostrophe &&
    marker !== Character.LeftParenthesis
  ) {
    return -1;
  }
  let end = start + 1;
  while (end < source.length) {
    const code = source.charCodeAt(end);
    if (code === close) {
      return end + 1;
    }
    if (code === Character.LineFeed || code === Character.CarriageReturn) {
      return -1;
    }
    end += code === Character.ReverseSolidus && end + 1 < source.length ? 2 : 1;
  }
  return -1;
}

const simpleLinkTail = /\([^<\\()\t\n\r ]+\)/y;

function scanLinkTail(source: string, start: number, tokens: number[]): number {
  simpleLinkTail.lastIndex = start + 1;
  // Fast path for simple inline link tails such as `](destination)`.
  if (simpleLinkTail.test(source)) {
    const end = simpleLinkTail.lastIndex;
    appendInlineToken(tokens, InlineKind.LinkTail, start, end, end - start - 1);
    return end;
  }
  if (source.charCodeAt(start + 1) !== Character.LeftParenthesis) {
    return -1;
  }
  let offset = skipWhitespace(source, start + 2);
  let destinationEnd = offset;
  if (source.charCodeAt(offset) !== Character.RightParenthesis) {
    destinationEnd = linkDestinationEnd(source, offset);
    if (destinationEnd < 0) {
      return -1;
    }
    offset = destinationEnd;
    const whitespaceEnd = skipWhitespace(source, offset);
    if (whitespaceEnd > offset && source.charCodeAt(whitespaceEnd) !== Character.RightParenthesis) {
      const titleEnd = linkTitleEnd(source, whitespaceEnd);
      if (titleEnd < 0) {
        return -1;
      }
      offset = skipWhitespace(source, titleEnd);
    }
    else {
      offset = whitespaceEnd;
    }
    if (source.charCodeAt(offset) !== Character.RightParenthesis) {
      return -1;
    }
  }
  const end = offset + 1;
  appendInlineToken(tokens, InlineKind.LinkTail, start, end, destinationEnd - start);
  return end;
}

function phrasingText(children: readonly PhrasingContent[]): string {
  let result = "";
  for (const child of children) {
    if (child.type === "text" || child.type === "inlineCode" || child.type === "html") {
      result += child.value;
    }
    else if (child.type === "break") {
      result += "\n";
    }
    else if ("children" in child) {
      result += phrasingText(child.children);
    }
    else if (child.type === "image" || child.type === "imageReference") {
      result += child.alt ?? "";
    }
  }
  return result;
}

function createBuildMedia(media: "image" | "link", resourceKind: "direct" | "reference"): InlinePairBuilder {
  const isImage = media === "image";
  const isReference = resourceKind === "reference";

  return isReference
    ? (openToken, closeToken, position, children, context) => {
      const closeText = inlineTokenText(context.view.text, context.tokens, closeToken);
      const syntaxStart = inlineTokenStart(context.tokens, openToken);
      const syntaxEnd = inlineTokenEnd(context.tokens, closeToken);
      const full = closeText.startsWith("][") && closeText !== "][]";
      const labelSource = full
        ? closeText.slice(2, -1)
        : context.view.text.slice(syntaxStart + (isImage ? 2 : 1), syntaxEnd - closeText.length);
      const identifier = normalizeIdentifier(labelSource);
      const label = semanticText(labelSource);
      const referenceType = full ? "full" : closeText === "][]" ? "collapsed" : "shortcut";
      return isImage
        ? {
          type: "imageReference",
          alt: phrasingText(children),
          identifier,
          label,
          referenceType,
          position,
        }
        : {
          type: "linkReference",
          children,
          identifier,
          label,
          referenceType,
          position,
        };
    }
    : (openToken, closeToken, position, children, context) => {
      let url = "";
      let title: string | null = null;

      const tokenStart = inlineTokenStart(context.tokens, closeToken);
      let end = inlineTokenEnd(context.tokens, closeToken) - 1;
      const resourceEnd = tokenStart + inlineTokenData(context.tokens, closeToken);
      let start = skipWhitespace(context.view.text, tokenStart + 2, resourceEnd);
      if (start !== end) {
        let destinationEnd = resourceEnd;
        if (context.view.text.charCodeAt(start) === Character.LessThanSign) {
          start++;
          destinationEnd--;
        }
        url = semanticText(context.view.text.slice(start, destinationEnd));
        start = skipWhitespace(context.view.text, resourceEnd, end);
        if (start < end) {
          while (end > start && isMarkdownWhitespace(context.view.text.charCodeAt(end - 1))) {
            end--;
          }
          title = semanticText(context.view.text.slice(start + 1, end - 1));
        }
      }

      return isImage
        ? {
          type: "image",
          alt: phrasingText(children),
          url,
          title,
          position,
        }
        : {
          type: "link",
          children,
          url,
          title,
          position,
        };
    };
}

const buildInlineImage = createBuildMedia("image", "direct");
const buildInlineReferenceImage = createBuildMedia("image", "reference");
const buildInlineLink = createBuildMedia("link", "direct");
const buildInlineReferenceLink = createBuildMedia("link", "reference");

export const feature: SyntaxFeature = {
  inline: {
    scans: [
      {
        marker: Character.ExclamationMark,
        scan(source, start, tokens) {
          if (source.charCodeAt(start + 1) !== Character.LeftSquareBracket) {
            return start + 1;
          }
          const end = start + 2;
          appendInlineToken(tokens, InlineKind.ImageOpen, start, end);
          return end;
        },
      },
      {
        marker: Character.LeftSquareBracket,
        scan(source, start, tokens) {
          const end = start + 1;
          appendInlineToken(tokens, InlineKind.BracketOpen, start, end);
          return end;
        },
      },
      {
        marker: Character.RightSquareBracket,
        scan(source, start, tokens) {
          const end = scanLinkTail(source, start, tokens);
          if (end >= 0) {
            return end;
          }
          appendInlineToken(tokens, InlineKind.BracketClose, start, start + 1);
          return start + 1;
        },
      },
    ],
    builds: [
      {
        kind: "pair",
        token: InlineKind.LinkOpen,
        build: buildInlineLink,
      },
      {
        kind: "pair",
        token: InlineKind.ImageLinkOpen,
        build: buildInlineImage,
      },
      {
        kind: "pair",
        token: InlineKind.ReferenceOpen,
        build: buildInlineReferenceLink,
      },
      {
        kind: "pair",
        token: InlineKind.ImageReferenceOpen,
        build: buildInlineReferenceImage,
      },
      {
        kind: "leaf",
        token: InlineKind.Autolink,
        build(tokenIndex, position, context) {
          const label = inlineTokenText(context.view.text, context.tokens, tokenIndex, 1);
          return {
            type: "link",
            url: label.includes(":") ? label : `mailto:${label}`,
            title: null,
            children: [
              {
                type: "text",
                value: label,
                position: {
                  start: {
                    line: position.start.line,
                    column: position.start.column + 1,
                    offset: position.start.offset + 1,
                  },
                  end: {
                    line: position.end.line,
                    column: position.end.column - 1,
                    offset: position.end.offset - 1,
                  },
                },
              },
            ],
            position,
          };
        },
      },
      { kind: "text", token: InlineKind.LinkTail, build: buildDecodedInlineText },
    ],
  },
};

import { blockBuilds, blockStarts } from "./block.ts";
import { inlineBuilds } from "./inline.ts";
import type { SyntaxFeature } from "../../types.ts";

export const feature: SyntaxFeature = {
  block: {
    builds: blockBuilds,
    starts: blockStarts,
  },
  inline: {
    builds: inlineBuilds,
  },
};

import { Character } from "../../../constants/character.ts";
import { isMarkdownWhitespace, normalizeIdentifier } from "../../utils.ts";

const footnoteDefinitionPrefix = "footnote\0";

export interface FootnoteLabel {
  definitionKey: string;
  end: number;
  label: string;
  normalizedLabel: string;
}

export function footnoteLabelAt(source: string, start: number, limit: number): FootnoteLabel | undefined {
  if (
    source.charCodeAt(start) !== Character.LeftSquareBracket ||
    source.charCodeAt(start + 1) !== Character.CircumflexAccent
  ) {
    return;
  }
  const labelStart = start + 2;
  let offset = labelStart;
  let length = 0;
  while (offset < limit) {
    const code = source.charCodeAt(offset);
    if (isMarkdownWhitespace(code)) {
      return;
    }
    if (code === Character.ReverseSolidus && offset + 1 < limit) {
      if (isMarkdownWhitespace(source.charCodeAt(offset + 1))) {
        return;
      }
      offset += 2;
      length += 2;
    }
    else if (code === Character.RightSquareBracket) {
      if (length === 0) {
        return;
      }
      const label = source.slice(labelStart, offset);
      const normalizedLabel = normalizeIdentifier(label);
      return {
        definitionKey: footnoteDefinitionPrefix + normalizedLabel,
        end: offset + 1,
        label,
        normalizedLabel,
      };
    }
    else {
      if (code === Character.LeftSquareBracket) {
        return;
      }
      offset++;
      length++;
    }
    if (length > 999) {
      return;
    }
  }
}

import type { FootnoteDefinition } from "mdast";
import {
  type BlockLines,
  IndentedLine,
  isBlankLine,
  trimLineWhitespaceStart,
} from "../../../block/lines.ts";
import { BlockKind } from "../../../constants/block.ts";
import { Character } from "../../../constants/character.ts";
import { buildBlockChildren } from "../../../fragment/block.ts";
import { semanticText } from "../../utils.ts";
import { type FootnoteLabel, footnoteLabelAt } from "./shared.ts";
import type { BlockFeature } from "../../../block/profile.ts";

interface FootnoteDefinitionFields {
  label: string;
  normalizedLabel: string;
}

interface FootnoteDefinitionMatch extends FootnoteLabel {
  contentOffset: number;
  markerEnd: number;
}

function definitionAt(
  source: string,
  lines: BlockLines,
  index: number,
  markerStart: number,
): FootnoteDefinitionMatch | undefined {
  const lineEnd = lines.end(index);
  const label = footnoteLabelAt(source, markerStart, lineEnd);
  if (!label || source.charCodeAt(label.end) !== Character.Colon) {
    return;
  }
  const markerEnd = label.end + 1;
  const contentOffset = trimLineWhitespaceStart(source, markerEnd, lineEnd);
  return {
    ...label,
    contentOffset,
    markerEnd,
  };
}

export const blockBuilds: BlockFeature["builds"] = [
  {
    token: BlockKind.FootnoteDefinitionOpen,
    build(tokenStart, context) {
      const tokens = context.structure.tokens;
      const close = tokenStart + tokens.nodeLength(tokenStart) - 1;
      const start = context.locator.locationAt(tokens.start(tokenStart));
      const children = buildBlockChildren<FootnoteDefinition["children"][number]>(tokenStart, context);
      // This rule only builds openers emitted with their parsed definition fields.
      const fields = tokens.value<FootnoteDefinitionFields>(tokenStart)!;
      return {
        type: "footnoteDefinition",
        identifier: fields.normalizedLabel,
        label: semanticText(fields.label),
        children,
        position: {
          start,
          end: context.locator.locationAt(tokens.end(close)),
        },
      };
    },
  },
];

export const blockStarts: BlockFeature["starts"] = [
  {
    codes: [
      Character.LeftSquareBracket,
    ],
    unwrapLazyContinuation(source, lines, index, contentOffset, target) {
      const match = definitionAt(source, lines, index, contentOffset);
      if (!match) {
        return false;
      }
      target.resetFrom(lines, index, match.contentOffset, 0);
      return true;
    },
    interrupt(source, lines, index, contentOffset) {
      return definitionAt(source, lines, index, contentOffset) !== void 0;
    },
    start(source, lines, tokens, start, contentOffset, context) {
      const match = definitionAt(source, lines, start, contentOffset);
      if (!match) {
        return;
      }
      const definitionLines = context.createLineView(lines, start, match.contentOffset, 0);
      let index = start + 1;
      let lazyParagraph: boolean | undefined;
      while (index < lines.length) {
        const line = definitionLines.pushAfterColumns(source, lines, index, 4);
        if (line === IndentedLine.Blank) {
          definitionLines.pushFrom(lines, index);
          lazyParagraph = false;
          index++;
          continue;
        }
        if (line === IndentedLine.Appended) {
          lazyParagraph = void 0;
          index++;
          continue;
        }
        lazyParagraph ??= context.endsWithParagraphLeaf(source, definitionLines, definitionLines.length - 1);
        if (
          !lazyParagraph ||
          !lines.lazy(index) &&
          context.startsInterruptingBlock(source, lines, index)
        ) {
          break;
        }
        definitionLines.pushLazy(lines, index);
        index++;
      }
      while (
        definitionLines.length > 0 &&
        isBlankLine(source, definitionLines, definitionLines.length - 1)
      ) {
        definitionLines.pop();
      }
      tokens.push(
        BlockKind.FootnoteDefinitionOpen,
        contentOffset,
        match.markerEnd,
        {
          definitionKey: match.definitionKey,
          value: {
            label: match.label,
            normalizedLabel: match.normalizedLabel,
          },
        },
      );
      context.scanLines(source, definitionLines, tokens);
      const end = definitionLines.length > 0
        ? definitionLines.next(definitionLines.length - 1)
        : match.markerEnd;
      tokens.push(BlockKind.FootnoteDefinitionClose, end, end);
      return index;
    },
  },
];

import { InlineKind } from "../../../constants/inline.ts";
import { inlineTokenText } from "../../../inline/tokens.ts";
import { normalizeIdentifier, semanticText } from "../../utils.ts";
import type { InlineBuildRule } from "../../../inline/profile.ts";

export const inlineBuilds: readonly InlineBuildRule[] = [
  {
    kind: "leaf",
    token: InlineKind.FootnoteReference,
    build(tokenIndex, position, context) {
      const label = inlineTokenText(context.view.text, context.tokens, tokenIndex, 2, 1);
      return {
        type: "footnoteReference",
        identifier: normalizeIdentifier(label),
        label: semanticText(label),
        position,
      };
    },
  },
];

import type { List, ListItem } from "mdast";
import { type BlockLines, IndentedLine, lineIndentOffset } from "../../block/lines.ts";
import { BlockKind } from "../../constants/block.ts";
import { Character } from "../../constants/character.ts";
import { type BlockNodeBuilder, buildBlockChildren } from "../../fragment/block.ts";
import { cloneLocation, type SourceLocation } from "../../source-view.ts";
import { isThematicBreak } from "./break.ts";
import type { BlockStart } from "../../block/profile.ts";
import type { BlockTokenStream } from "../../block/tokens.ts";
import type { SyntaxFeature } from "../types.ts";

interface ListMarker {
  offset: number;
  end: number;
  hasContent: boolean;
  contentOffset: number;
  contentIndent: number;
  contentPrefixColumns: number;
  delimiter: number;
  startNumber: number;
}

const enum ParagraphLeafState {
  No,
  Yes,
  Unknown,
}

function listMarkerAt(
  source: string,
  lines: BlockLines,
  index: number,
  contentOffset: number,
): ListMarker | undefined {
  if (contentOffset < 0) {
    return;
  }
  const indent = lines.prefixColumns(index) + contentOffset - lines.start(index);
  const marker = source.charCodeAt(contentOffset);
  const lineEnd = lines.end(index);
  let delimiter: number;
  let markerEnd = contentOffset + 1;
  let startNumber = 0;
  if (
    marker === Character.HyphenMinus ||
    marker === Character.PlusSign ||
    marker === Character.Asterisk
  ) {
    const following = source.charCodeAt(markerEnd);
    if (
      (
        markerEnd !== lineEnd &&
        following !== Character.Space &&
        following !== Character.CharacterTabulation
      ) ||
      isThematicBreak(source, lines, index, contentOffset)
    ) {
      return;
    }
    delimiter = marker;
  }
  else {
    if (marker < Character.DigitZero || marker > Character.DigitNine) {
      return;
    }
    let orderedEnd = contentOffset;
    // CommonMark caps ordered markers at nine digits, so the prefix is cheaper to scan than to slice and match.
    while (orderedEnd < lineEnd && orderedEnd - contentOffset < 9) {
      const digit = source.charCodeAt(orderedEnd) - Character.DigitZero;
      if (digit < 0 || digit > 9) {
        break;
      }
      startNumber = startNumber * 10 + digit;
      orderedEnd++;
    }
    delimiter = source.charCodeAt(orderedEnd);
    if (delimiter !== Character.FullStop && delimiter !== Character.RightParenthesis) {
      return;
    }
    if (orderedEnd + 1 < lineEnd) {
      const code = source.charCodeAt(orderedEnd + 1);
      if (code !== Character.Space && code !== Character.CharacterTabulation) {
        return;
      }
    }
    markerEnd = orderedEnd + 1;
  }

  const markerColumn = indent + markerEnd - contentOffset;
  let contentIndent = markerColumn + 1;
  let contentStart = markerEnd;
  let hasContent = false;
  let prefixColumns = 0;
  if (markerEnd < lineEnd) {
    let column = markerColumn;
    while (contentStart < lineEnd) {
      const code = source.charCodeAt(contentStart);
      if (code === Character.Space) {
        column++;
      }
      else if (code === Character.CharacterTabulation) {
        column += 4 - (column % 4);
      }
      else {
        break;
      }
      contentStart++;
    }
    hasContent = contentStart < lineEnd;
    if (hasContent && column - markerColumn <= 4) {
      contentIndent = column;
    }
    else {
      const firstPaddingColumns = source.charCodeAt(markerEnd) === Character.CharacterTabulation
        ? 4 - (markerColumn % 4)
        : 1;
      contentStart = markerEnd + 1;
      prefixColumns = firstPaddingColumns - 1;
    }
  }
  return {
    offset: contentOffset,
    end: markerEnd,
    hasContent,
    contentOffset: contentStart,
    contentIndent,
    contentPrefixColumns: prefixColumns,
    delimiter,
    startNumber,
  };
}

interface TaskListMarker {
  checked: boolean;
  contentStart: number;
}

function isTaskListWhitespace(code: number): boolean {
  return code === Character.Space || (
    code >= Character.CharacterTabulation && code <= Character.CarriageReturn
  );
}

function taskListMarkerAt(source: string, start: number, end: number): TaskListMarker | undefined {
  while (source.charCodeAt(start) === Character.Space) {
    start++;
  }
  if (source.charCodeAt(start++) !== Character.LeftSquareBracket) {
    return;
  }
  const state = source.charCodeAt(start++);
  const checked = state === Character.LatinCapitalLetterX || state === Character.LatinSmallLetterX;
  if (!checked && !isTaskListWhitespace(state)) {
    return;
  }
  if (source.charCodeAt(start++) !== Character.RightSquareBracket) {
    return;
  }
  if (start >= end) {
    return;
  }
  const whitespace = source.charCodeAt(start++);
  if (!isTaskListWhitespace(whitespace)) {
    return;
  }
  if (
    whitespace === Character.CarriageReturn &&
    source.charCodeAt(start) === Character.LineFeed
  ) {
    start++;
  }
  return {
    checked,
    contentStart: start,
  };
}

function hasTaskListContent(
  source: string,
  tokens: BlockTokenStream,
  firstChunk: number,
  contentStart: number,
): boolean {
  const tokenEnd = firstChunk - 1 + tokens.nodeLength(firstChunk - 1);
  for (let token = firstChunk; token < tokenEnd; token++) {
    const start = token === firstChunk ? contentStart : tokens.start(token);
    const end = tokens.end(token);
    for (let offset = start; offset < end; offset++) {
      if (!isTaskListWhitespace(source.charCodeAt(offset))) {
        return true;
      }
    }
  }
  return false;
}

const buildListItem: BlockNodeBuilder<ListItem> = (tokenStart, context) => {
  const tokens = context.structure.tokens;
  const markerKind = tokens.kind(tokenStart);
  const close = tokenStart + tokens.nodeLength(tokenStart) - 1;
  const start = context.locator.locationAt(tokens.start(tokenStart));
  const children = buildBlockChildren<ListItem["children"][number]>(tokenStart, context);
  return {
    type: "listItem",
    spread: tokens.kind(close) === BlockKind.ListItemSpreadClose,
    checked: markerKind === BlockKind.CheckedTaskItemOpen
      ? true
      : markerKind === BlockKind.UncheckedTaskItemOpen ? false : null,
    children,
    position: {
      start,
      end: children.length
        ? cloneLocation(children.at(-1)!.position!.end as SourceLocation)
        : context.locator.locationAt(tokens.end(close)),
    },
  };
};

function listStartNumber(
  source: string,
  tokens: BlockTokenStream,
  tokenStart: number,
): number {
  // The ordered marker span is exactly its digits plus one delimiter character.
  const digits = source.slice(tokens.start(tokenStart), tokens.end(tokenStart) - 1);
  return Number(digits);
}

function createBuildList(ordered: boolean): BlockNodeBuilder<List> {
  return (tokenStart, context) => {
    const tokens = context.structure.tokens;
    const close = tokenStart + tokens.nodeLength(tokenStart) - 1;
    const start = context.locator.locationAt(tokens.start(tokenStart));
    const children = buildBlockChildren<ListItem>(tokenStart, context);
    return {
      type: "list",
      ordered,
      start: ordered ? listStartNumber(context.source, tokens, tokenStart) : null,
      spread: tokens.kind(close) === BlockKind.ListSpreadClose,
      children,
      position: {
        start,
        end: cloneLocation(children.at(-1)!.position!.end as SourceLocation),
      },
    };
  };
}

const listStart: BlockStart = (source, lines, tokens, start, contentOffset, context) => {
  let marker = listMarkerAt(source, lines, start, contentOffset);
  if (!marker) {
    return;
  }
  const delimiter = marker.delimiter;
  const ordered = delimiter === Character.FullStop || delimiter === Character.RightParenthesis;
  const listOpen = ordered ? BlockKind.OrderedListOpen : BlockKind.UnorderedListOpen;
  tokens.push(listOpen, marker.offset, marker.end);
  let index = start;
  let listEnd = marker.end;
  let listSpread = false;
  let trailingBlank = false;
  while (marker?.delimiter === delimiter) {
    let sibling: ListMarker | undefined;
    // A trailing blank affects the list only when another sibling follows it.
    listSpread ||= trailingBlank;
    trailingBlank = false;
    tokens.push(BlockKind.ListItemOpen, marker.offset, marker.end);
    const itemLines = context.createLineView(
      lines,
      index,
      marker.contentOffset,
      marker.contentPrefixColumns,
    );
    let hasContent = marker.hasContent;
    // Probe the paragraph leaf only when an underindented line needs lazy continuation.
    let paragraphLeaf = hasContent ? ParagraphLeafState.Unknown : ParagraphLeafState.No;
    index++;
    while (index < lines.length) {
      const line = itemLines.pushAfterColumns(source, lines, index, marker.contentIndent);
      if (line === IndentedLine.Blank) {
        if (!hasContent) {
          trailingBlank = true;
          index++;
          sibling = index < lines.length
            ? listMarkerAt(source, lines, index, lineIndentOffset(source, lines, index))
            : void 0;
          break;
        }
        itemLines.pushFrom(lines, index);
        trailingBlank = true;
        paragraphLeaf = ParagraphLeafState.No;
        index++;
        continue;
      }
      if (line === IndentedLine.Appended) {
        trailingBlank = false;
        hasContent = true;
        paragraphLeaf = ParagraphLeafState.Unknown;
        index++;
        continue;
      }
      // Only underindented content reaches here, so any marker starts a sibling item.
      const contentOffset = lineIndentOffset(source, lines, index);
      const candidate = listMarkerAt(
        source,
        lines,
        index,
        contentOffset,
      );
      if (candidate) {
        sibling = candidate;
        break;
      }
      if (paragraphLeaf === ParagraphLeafState.Unknown) {
        paragraphLeaf = context.endsWithParagraphLeaf(source, itemLines, itemLines.length - 1)
          ? ParagraphLeafState.Yes
          : ParagraphLeafState.No;
      }
      if (
        paragraphLeaf === ParagraphLeafState.No ||
        context.startsInterruptingBlock(source, lines, index, contentOffset)
      ) {
        break;
      }
      itemLines.pushLazy(lines, index);
      index++;
    }
    const itemSpread = context.scanLines(source, itemLines, tokens);
    // Close positions exclude the terminal line ending; outer list scans retain it.
    const itemEnd = itemLines.length ? itemLines.end(itemLines.length - 1) : marker.end;
    // A frame's blank-separation summary is known only when its close is emitted.
    tokens.push(itemSpread ? BlockKind.ListItemSpreadClose : BlockKind.ListItemClose, itemEnd, itemEnd);
    listEnd = itemEnd;
    marker = sibling;
  }
  tokens.push(listSpread ? BlockKind.ListSpreadClose : BlockKind.ListClose, listEnd, listEnd);
  return index;
};

const taskListStart: BlockStart = (source, lines, tokens, start, contentOffset, context) => {
  const listToken = tokens.length;
  const nextLine = listStart(source, lines, tokens, start, contentOffset, context);
  if (nextLine === void 0) {
    return;
  }
  // List node lengths jump over nested frames; task variants refine direct item kinds in place.
  for (let item = listToken + 1; item < tokens.length - 1; item += tokens.nodeLength(item)) {
    let paragraph = item + 1;
    let contentKind = tokens.kind(paragraph);
    // Link definition leaves do not count as the item's first content block.
    while (contentKind === BlockKind.LinkDefinition) {
      paragraph += tokens.nodeLength(paragraph);
      contentKind = tokens.kind(paragraph);
    }
    if (contentKind !== BlockKind.ParagraphOpen) {
      continue;
    }
    const firstChunk = paragraph + 1;
    const marker = taskListMarkerAt(
      source,
      tokens.start(firstChunk),
      tokens.end(firstChunk),
    );
    if (!marker || !hasTaskListContent(source, tokens, firstChunk, marker.contentStart)) {
      continue;
    }
    tokens.setKind(
      item,
      marker.checked ? BlockKind.CheckedTaskItemOpen : BlockKind.UncheckedTaskItemOpen,
    );
    tokens.setStart(firstChunk, marker.contentStart);
  }
  return nextLine;
};

export function feature(taskList = false): SyntaxFeature {
  return {
    block: {
      builds: [
        {
          token: [
            BlockKind.ListItemOpen,
            BlockKind.UncheckedTaskItemOpen,
            BlockKind.CheckedTaskItemOpen,
          ],
          build: buildListItem,
        },
        {
          token: BlockKind.UnorderedListOpen,
          build: createBuildList(false),
        },
        {
          token: BlockKind.OrderedListOpen,
          build: createBuildList(true),
        },
      ],
      starts: [
        {
          codes: [
            Character.Asterisk,
            Character.PlusSign,
            Character.HyphenMinus,
            Character.DigitZero,
            Character.DigitOne,
            Character.DigitTwo,
            Character.DigitThree,
            Character.DigitFour,
            Character.DigitFive,
            Character.DigitSix,
            Character.DigitSeven,
            Character.DigitEight,
            Character.DigitNine,
          ],
          unwrapLazyContinuation(source, lines, index, contentOffset, target) {
            const marker = listMarkerAt(source, lines, index, contentOffset);
            if (!marker) {
              return false;
            }
            target.resetFrom(lines, index, marker.contentOffset, marker.contentPrefixColumns);
            return true;
          },
          interrupt(source, lines, index, contentOffset) {
            const marker = listMarkerAt(source, lines, index, contentOffset);
            return marker?.hasContent === true && (
              marker.startNumber === 1 || (
                marker.delimiter !== Character.FullStop &&
                marker.delimiter !== Character.RightParenthesis
              )
            );
          },
          start: taskList ? taskListStart : listStart,
        },
      ],
    },
  };
}

import type { Yaml } from "mdast";
import { type BlockLines, trimLineWhitespaceStart } from "../../block/lines.ts";
import { appendLogicalToken } from "../../block/tokens.ts";
import { BlockKind } from "../../constants/block.ts";
import { type BlockNodeBuilder, leafBlockPosition } from "../../fragment/block.ts";
import type { SyntaxFeature } from "../types.ts";

export type FrontmatterMarker = "+" | "-";

export interface FrontmatterOptions {
  marker: FrontmatterMarker;
}

function frontmatterFenceAt(
  source: string,
  lines: BlockLines,
  index: number,
  marker: FrontmatterMarker,
): boolean {
  const start = lines.start(index);
  if (
    source[start] !== marker ||
    source[start + 1] !== marker ||
    source[start + 2] !== marker
  ) {
    return false;
  }
  const end = lines.end(index);
  return trimLineWhitespaceStart(source, start + 3, end) === end;
}

export const buildYamlBlock: BlockNodeBuilder<Yaml> = (tokenStart, context) => {
  const tokens = context.structure.tokens;
  const text = context.locator.normalizeLineEndings(
    tokens.text(context.source, tokenStart),
  );
  const contentStart = text.indexOf("\n") + 1;
  const closingEnd = text.endsWith("\n") ? text.length - 1 : text.length;
  const closingStart = text.lastIndexOf("\n", closingEnd - 1) + 1;
  return {
    type: "yaml",
    value: text.slice(contentStart, Math.max(contentStart, closingStart - 1)),
    position: leafBlockPosition(tokenStart, context),
  };
};

export function feature(marker: FrontmatterMarker): SyntaxFeature {
  return {
    block: {
      builds: [
        {
          token: BlockKind.Frontmatter,
          build: buildYamlBlock,
        },
      ],
      starts: [
        {
          codes: [marker.charCodeAt(0)],
          start(source, lines, tokens, start, contentOffset, context) {
            if (lines.start(start) !== 0 || !frontmatterFenceAt(source, lines, start, marker)) {
              return;
            }
            for (let end = start + 1; end < lines.length; end++) {
              if (frontmatterFenceAt(source, lines, end, marker)) {
                appendLogicalToken(source, lines, tokens, BlockKind.Frontmatter, start, end + 1);
                return end + 1;
              }
            }
            // A closing fence appended after this failed probe can reinterpret the document from offset 0.
            context.retainLookahead(lines.next(lines.length - 1));
          },
        },
      ],
    },
  };
}

import { htmlBlockNames, htmlRawNames } from "micromark-util-html-tag-name";
import { type BlockLines, isBlankLine } from "../../block/lines.ts";
import { appendLogicalToken } from "../../block/tokens.ts";
import { BlockKind } from "../../constants/block.ts";
import { Character } from "../../constants/character.ts";
import { InlineKind } from "../../constants/inline.ts";
import { matchInlinePatternEnd } from "../../inline/tokenizer.ts";
import { appendInlineToken, inlineTokenText } from "../../inline/tokens.ts";
import type { InlineLeafBuilder } from "../../fragment/inline.ts";
import type { SyntaxFeature } from "../types.ts";

interface HtmlStart {
  interruptParagraph: boolean;
  terminator?: string;
}

const htmlBlockTags = new Set(htmlBlockNames);
const htmlRawTags = new Set(htmlRawNames);
const htmlTagName = "[a-z][a-z0-9-]*";
const htmlAttributeName = "[a-z_:][\\w.:-]*";
const htmlUnquotedValue = `[^\\s"'=<>\`]+`;
const htmlAttributeValue = `(?:${htmlUnquotedValue}|'[^']*'|"[^"]*")`;
const htmlAttribute = `\\s+${htmlAttributeName}(?:\\s*=\\s*${htmlAttributeValue})?`;
const completeHtmlTag = new RegExp(`^(?:<${htmlTagName}(?:${htmlAttribute})*\\s*/?>|</${htmlTagName}\\s*>)[ \\t]*$`, "i");
const htmlComment = /<!-->|<!--->|<!--[\s\S]*?(?:-->|$)/y;
const autolink = /<(?:[A-Z][A-Z0-9+.\-]{1,31}:[^ \t\n\r<>]+|[\w!#$%&'*+\-/=?^`{|}~.]+@[A-Z0-9](?:[A-Z0-9]|-(?=[A-Z0-9]))*(?:\.[A-Z0-9](?:[A-Z0-9]|-(?=[A-Z0-9]))*)+)>/iy;
const inlineHtml = /<[A-Za-z][A-Za-z0-9-]*(?:[ \t\n\r]+[A-Za-z_:][\w.:-]*(?:[ \t\n\r]*=[ \t\n\r]*(?:[^ \t\n\r"'=<>`]+|'[^']*'|"[^"]*"))?)*[ \t\n\r]*\/?>|<\/[A-Za-z][A-Za-z0-9-]*[ \t\n\r]*>|<\?[\s\S]*?\?>|<![A-Z][\s\S]*?>|<!\[CDATA\[[\s\S]*?\]\]>/y;

function htmlStartAt(
  source: string,
  lines: BlockLines,
  index: number,
  contentOffset: number,
): HtmlStart | undefined {
  const body = source.slice(contentOffset, lines.end(index));
  switch (body.charCodeAt(1)) {
    case Character.QuestionMark: {
      return { interruptParagraph: true, terminator: "?>" };
    }
    case Character.ExclamationMark: {
      if (body.startsWith("<!--")) {
        return { interruptParagraph: true, terminator: "-->" };
      }
      if (body.startsWith("<![CDATA[")) {
        return { interruptParagraph: true, terminator: "]]>" };
      }
      if (/[A-Z]/.test(body[2] ?? "")) {
        return { interruptParagraph: true, terminator: ">" };
      }
      break;
    }
  }
  const tag = /^<\/?([a-z][a-z0-9-]*)(?=[ \t\n\r/>]|$)/i.exec(body)?.[1].toLowerCase();
  if (
    tag && body[1] !== "/" && htmlRawTags.has(tag) && (
      body.length === tag.length + 1 || /[ \t>]/.test(body[tag.length + 1])
    )
  ) {
    return { interruptParagraph: true, terminator: `</${tag}>` };
  }
  if (tag && htmlBlockTags.has(tag)) {
    return { interruptParagraph: true };
  }
  if (completeHtmlTag.test(body)) {
    return { interruptParagraph: false };
  }
}

const buildInlineHtml: InlineLeafBuilder = (tokenIndex, position, context) => {
  const text = inlineTokenText(context.view.text, context.tokens, tokenIndex);
  return {
    type: "html",
    value: text,
    position,
  };
};

export const feature: SyntaxFeature = {
  block: {
    builds: [
      {
        token: BlockKind.HtmlBlock,
        build(tokenStart, context) {
          const tokens = context.structure.tokens;
          const offset = tokens.start(tokenStart);
          const end = tokens.end(tokenStart);
          // The HTML scanner records termination state on every emitted block token.
          const unterminated = tokens.value<boolean>(tokenStart)!;
          let html = context.locator.normalizeLineEndings(
            tokens.text(context.source, tokenStart),
          );
          if (!unterminated && html.endsWith("\n")) {
            html = html.slice(0, -1);
          }
          return {
            type: "html",
            value: html,
            position: context.locator.positionAt(
              offset,
              html.endsWith("\n") ? end : tokens.contentEnd(context.source, tokenStart),
            ),
          };
        },
      },
    ],
    starts: [
      {
        codes: [
          Character.LessThanSign,
        ],
        interrupt(source, lines, index, contentOffset) {
          return !!htmlStartAt(source, lines, index, contentOffset)?.interruptParagraph;
        },
        start(source, lines, tokens, start, contentOffset) {
          const htmlStart = htmlStartAt(source, lines, start, contentOffset);
          if (!htmlStart) {
            return;
          }
          let end = start;
          let unterminated = false;
          if (htmlStart.terminator) {
            while (
              end < lines.length &&
              !source.slice(lines.start(end), lines.end(end)).toLowerCase().includes(htmlStart.terminator)
            ) {
              end++;
            }
            if (end === lines.length) {
              unterminated = true;
            }
            else {
              end++;
            }
          }
          else {
            end++;
            while (end < lines.length && !isBlankLine(source, lines, end)) {
              end++;
            }
          }
          appendLogicalToken(source, lines, tokens, BlockKind.HtmlBlock, start, end, unterminated);
          return end;
        },
      },
    ],
  },
  inline: {
    scans: [
      {
        marker: Character.LessThanSign,
        scan(source, start, tokens) {
          let end = matchInlinePatternEnd(htmlComment, source, start);
          let kind = InlineKind.HtmlComment;
          if (end < 0) {
            end = matchInlinePatternEnd(autolink, source, start);
            kind = InlineKind.Autolink;
          }
          if (end < 0) {
            end = matchInlinePatternEnd(inlineHtml, source, start);
            kind = InlineKind.InlineHtml;
          }
          if (end < 0) {
            return start + 1;
          }
          appendInlineToken(tokens, kind, start, end);
          return end;
        },
      },
    ],
    builds: [
      { kind: "leaf", token: InlineKind.InlineHtml, build: buildInlineHtml },
      { kind: "leaf", token: InlineKind.HtmlComment, build: buildInlineHtml },
    ],
  },
};

import {
  appendFencedToken,
  closesFence,
  createFenceRule,
  type Fence,
  fenceAt,
} from "../../block/fence.ts";
import { type BlockLines, isBlankLine, lineIndentOffset, physicalColumnAt } from "../../block/lines.ts";
import { BlockKind } from "../../constants/block.ts";
import { Character } from "../../constants/character.ts";
import { InlineKind } from "../../constants/inline.ts";
import { inlineMarkerRunEnd } from "../../inline/tokenizer.ts";
import { appendInlineToken, inlineTokenData, inlineTokenText } from "../../inline/tokens.ts";
import { semanticText } from "../utils.ts";
import type { SyntaxFeature } from "../types.ts";

const codeFenceRule = createFenceRule({
  alternateMarker: Character.Tilde,
  forbiddenInfoMarker: Character.GraveAccent,
  marker: Character.GraveAccent,
  minimumLength: 3,
});

export function codeFenceAt(
  source: string,
  lines: BlockLines,
  index: number,
  markerOffset: number,
): Fence | undefined {
  return fenceAt(source, lines, index, codeFenceRule, markerOffset);
}

/** Consume structural code indentation before publishing the literal body. */
function indentedContent(source: string, lines: BlockLines, start: number, end: number): string {
  const parts: string[] = [];
  for (let index = start; index < end; index++) {
    let offset = lines.start(index);
    let columns = lines.prefixColumns(index);
    const lineEnd = lines.end(index);
    while (offset < lineEnd && columns < 4) {
      const code = source.charCodeAt(offset);
      if (code === Character.Space) {
        columns++;
      }
      else if (code === Character.CharacterTabulation) {
        columns += Math.max(4 - columns, 4 - physicalColumnAt(source, offset) % 4);
      }
      else {
        break;
      }
      offset++;
    }
    parts.push(" ".repeat(Math.max(0, columns - 4)) + source.slice(offset, lineEnd));
  }
  return parts.join("\n");
}

export const feature: SyntaxFeature = {
  block: {
    builds: [
      {
        token: [
          BlockKind.FencedCodeBlock,
          BlockKind.IndentedCodeBlock,
        ],
        build(tokenStart, context) {
          const tokens = context.structure.tokens;
          const rawInfo = semanticText(tokens.value<string>(tokenStart) ?? "");
          const langEnd = rawInfo.search(/[ \t]/);
          const lang = rawInfo ? langEnd < 0 ? rawInfo : rawInfo.slice(0, langEnd) : null;
          const metaStart = langEnd < 0 ? -1 : rawInfo.slice(langEnd).search(/[^ \t]/);
          return {
            type: "code",
            lang,
            meta: metaStart < 0 ? null : rawInfo.slice(langEnd + metaStart),
            value: tokens.text(context.source, tokenStart),
            position: context.locator.positionAt(tokens.start(tokenStart), tokens.end(tokenStart)),
          };
        },
      },
    ],
    starts: [
      {
        codes: [
          Character.VirtualBlockIndent,
        ],
        start(source, lines, tokens, start) {
          let end = start + 1;
          while (end < lines.length && lineIndentOffset(source, lines, end) < 0) {
            end++;
          }
          // The block consumes trailing blank lines, but its code value and position do not include them.
          let contentEnd = end;
          while (contentEnd > start && isBlankLine(source, lines, contentEnd - 1)) {
            contentEnd--;
          }
          tokens.push(BlockKind.IndentedCodeBlock, lines.start(start), lines.end(contentEnd - 1), {
            text: indentedContent(source, lines, start, contentEnd),
          });
          return end;
        },
      },
      {
        codes: [
          Character.GraveAccent,
          Character.Tilde,
        ],
        interrupt(source, lines, index, contentOffset) {
          return !!codeFenceAt(source, lines, index, contentOffset);
        },
        start(source, lines, tokens, start, contentOffset) {
          const fence = codeFenceAt(source, lines, start, contentOffset);
          if (!fence) {
            return;
          }
          let end = start + 1;
          while (end < lines.length && !closesFence(source, lines, end, fence)) {
            end++;
          }
          const closed = end < lines.length;
          if (end < lines.length) {
            end++;
          }
          appendFencedToken(
            source,
            lines,
            tokens,
            BlockKind.FencedCodeBlock,
            start,
            end,
            fence,
            closed,
            true,
          );
          return end;
        },
      },
    ],
  },
  inline: {
    scans: [
      {
        marker: Character.GraveAccent,
        scan(source, start, tokens) {
          const openEnd = inlineMarkerRunEnd(source, start);
          if (source.charCodeAt(start - 1) === Character.GraveAccent) {
            return openEnd;
          }
          const markerLength = openEnd - start;
          let offset = openEnd;
          while (offset < source.length) {
            offset = source.indexOf("`", offset);
            if (offset < 0) {
              break;
            }
            const closeEnd = inlineMarkerRunEnd(source, offset);
            if (closeEnd - offset === markerLength) {
              appendInlineToken(tokens, InlineKind.CodeSpan, start, closeEnd, markerLength);
              return closeEnd;
            }
            offset = closeEnd;
          }
          return openEnd;
        },
      },
    ],
    builds: [
      {
        kind: "leaf",
        token: InlineKind.CodeSpan,
        build: (tokenIndex, position, context) => {
          const markerLength = inlineTokenData(context.tokens, tokenIndex);
          let value = context.locator.normalizeLineEndings(
            inlineTokenText(context.view.text, context.tokens, tokenIndex, markerLength),
          );
          if (/^[ \n]/.test(value) && /[ \n]$/.test(value) && /[^ \n]/.test(value)) {
            value = value.slice(1, -1);
          }
          return {
            type: "inlineCode",
            value: context.tableCell ? value.replace(/\\\|/g, "|") : value,
            position,
          };
        },
      },
    ],
  },
};

import { Character } from "../../constants/character.ts";
import { InlineKind } from "../../constants/inline.ts";
import { inlineMarkerRunEnd, type InlineScanRule } from "../../inline/tokenizer.ts";
import { appendInlineToken } from "../../inline/tokens.ts";
import type { DelimiterConfig } from "../../inline/delimiter.ts";
import type { InlineBuildRule } from "../../inline/profile.ts";
import type { SyntaxFeature } from "../types.ts";

interface Formatting {
  delimiter: DelimiterConfig;
  scanner: InlineScanRule;
  builder: InlineBuildRule;
}

function createFormatting(
  type: "emphasis" | "strong" | "delete",
  marker: Character,
  buildToken: InlineKind,
  delimiter: DelimiterConfig,
): Formatting {
  return {
    delimiter,
    scanner: {
      marker,
      scan(source, start, tokens) {
        const end = inlineMarkerRunEnd(source, start);
        appendInlineToken(tokens, delimiter.token, start, end);
        return end;
      },
    },
    builder: {
      kind: "pair",
      token: buildToken,
      build: (openToken, closeToken, position, children) => ({
        type,
        children,
        position,
      }),
    },
  };
}

const formattingAsterisk = createFormatting("emphasis", Character.Asterisk, InlineKind.EmphasisOpen, {
  token: InlineKind.AsteriskRun,
  single: {
    open: InlineKind.EmphasisOpen,
    close: InlineKind.EmphasisClose,
  },
  double: {
    open: InlineKind.StrongOpen,
    close: InlineKind.StrongClose,
  },
  pairing: {
    kind: "partial",
    ruleOfThree: true,
  },
});

const formattingUnderscore = createFormatting("strong", Character.LowLine, InlineKind.StrongOpen, {
  token: InlineKind.UnderscoreRun,
  single: {
    open: InlineKind.EmphasisOpen,
    close: InlineKind.EmphasisClose,
  },
  double: {
    open: InlineKind.StrongOpen,
    close: InlineKind.StrongClose,
  },
  pairing: {
    kind: "partial",
    ruleOfThree: true,
  },
  allowIntraword: false,
});

const formattingStrikethrough = createFormatting("delete", Character.Tilde, InlineKind.DeleteOpen, {
  token: InlineKind.TildeRun,
  double: {
    open: InlineKind.DeleteOpen,
    close: InlineKind.DeleteClose,
  },
  pairing: {
    kind: "whole",
  },
});

export interface StrikethroughOptions {
  singleTilde?: boolean;
}

export function feature(strikethroughOptions?: boolean | StrikethroughOptions): SyntaxFeature {
  const scans = [
    formattingAsterisk.scanner,
    formattingUnderscore.scanner,
  ];
  const delimiters = [
    formattingAsterisk.delimiter,
    formattingUnderscore.delimiter,
  ];
  const builds = [
    formattingAsterisk.builder,
    formattingUnderscore.builder,
  ];

  if (strikethroughOptions) {
    scans.push(formattingStrikethrough.scanner);
    builds.push(formattingStrikethrough.builder);
    delimiters.push(
      typeof strikethroughOptions !== "object" || strikethroughOptions.singleTilde !== false
        ? {
          single: formattingStrikethrough.delimiter.double,
          ...formattingStrikethrough.delimiter,
        }
        : formattingStrikethrough.delimiter,
    );
  }

  return {
    inline: {
      scans,
      delimiters,
      builds,
    },
  };
}

import { blockDecorators } from "./block.ts";
import { inlineBuilds, inlineScans } from "./inline.ts";
import type { SyntaxFeature } from "../../types.ts";

export const feature: SyntaxFeature = {
  block: {
    decorators: blockDecorators,
  },
  inline: {
    scans: inlineScans,
    builds: inlineBuilds,
  },
};

export type AttributeValue =
  | string
  | number
  | boolean
  | null
  | AttributeValue[]
  | { [key: string]: AttributeValue };

export type Attributes = Record<string, AttributeValue>;

declare module "mdast" {
  interface Node {
    attributes?: Attributes;
  }
}

import { trimLineWhitespaceStart } from "../../../block/lines.ts";
import { Character } from "../../../constants/character.ts";
import { isAsciiDigit, isAsciiLetter } from "../../utils.ts";
import type { Attributes, AttributeValue } from "./types.ts";

const brackets = {
  [Character.LeftSquareBracket as number]: Character.RightSquareBracket,
  [Character.LeftCurlyBracket as number]: Character.RightCurlyBracket,
  [Character.LeftParenthesis as number]: Character.RightParenthesis,
};

const stops1 = new Set([
  Character.Space,
  Character.NumberSign,
  Character.FullStop,
  Character.RightCurlyBracket,
]);
const stops2 = new Set([
  Character.Space,
  Character.RightCurlyBracket,
]);

function assignAttribute(attributes: Attributes, name: string, value: AttributeValue): void {
  if (name === "class" && typeof value === "string" && typeof attributes.class === "string") {
    attributes.class += ` ${value}`;
  }
  else {
    attributes[name] = value;
  }
}

export function mergeAttributes(target: Attributes, source: Attributes): void {
  for (const key in source) {
    assignAttribute(target, key, source[key]);
  }
}

function scanAttributes(
  source: string,
  start: number,
  attributes?: Attributes,
  limit = source.length,
): number | undefined {
  if (
    source.charCodeAt(start) !== Character.LeftCurlyBracket ||
    source.charCodeAt(start + 1) === Character.LeftCurlyBracket
  ) {
    return;
  }
  let offset = start + 1;

  // Scans only advance ranges; validation never materializes attribute strings.
  const scanUntil = (stops: Set<number>): void => {
    while (offset < limit) {
      const code = source.charCodeAt(offset);
      if (code === Character.LineFeed || code === Character.CarriageReturn || stops.has(code)) {
        break;
      }
      offset += code === Character.ReverseSolidus && offset + 1 < limit ? 2 : 1;
    }
  };

  const scanQuoted = (quote: number): boolean => {
    offset++;
    while (offset < limit) {
      const character = source.charCodeAt(offset);
      if (
        character === quote ||
        character === Character.LineFeed ||
        character === Character.CarriageReturn
      ) {
        break;
      }
      offset += character === Character.ReverseSolidus && offset + 1 < limit ? 2 : 1;
    }
    if (source.charCodeAt(offset) !== quote) {
      return false;
    }
    offset++;
    return true;
  };

  const scanBracketed = (close: number): boolean => {
    const stack = [close];
    offset++;
    while (offset < limit && stack.length > 0) {
      const code = source.charCodeAt(offset);
      if (code === Character.LineFeed || code === Character.CarriageReturn) {
        return false;
      }
      if (code === Character.ReverseSolidus && offset + 1 < limit) {
        offset += 2;
        continue;
      }
      if (
        code === Character.QuotationMark ||
        code === Character.Apostrophe ||
        code === Character.GraveAccent
      ) {
        if (!scanQuoted(code)) {
          return false;
        }
        continue;
      }
      const nested = brackets[code];
      if (nested) {
        stack.push(nested);
      }
      else if (code === stack.at(-1)) {
        stack.pop();
      }
      offset++;
    }
    return stack.length === 0;
  };

