  tokens.push(BlockKind.TableRowClose, lineEnd, lineEnd);
}

const buildTableCell: BlockNodeBuilder<TableCell> = (tokenStart, context) => {
  const tokens = context.structure.tokens;
  const start = context.locator.locationAt(tokens.start(tokenStart));
  const children = buildInlineFragment(tokenStart, true, context).children;
  return {
    type: "tableCell",
    children,
    position: {
      start,
      end: context.locator.locationAt(
        tokens.start(tokenStart + tokens.nodeLength(tokenStart)),
      ),
    },
  };
};

const buildTableRow: BlockNodeBuilder<TableRow> = (tokenStart, context) => {
  const tokens = context.structure.tokens;
  const close = tokenStart + tokens.nodeLength(tokenStart) - 1;
  const start = context.locator.locationAt(tokens.start(tokenStart));
  const children = buildBlockChildren<TableCell>(tokenStart, context);
  return {
    type: "tableRow",
    children,
    position: {
      start,
      end: context.locator.locationAt(tokens.start(close)),
    },
  };
};

function tableAlignment(
  tokenStart: number,
  context: BlockBuildContext,
): AlignType[] {
  const tokens = context.structure.tokens;
  const result: AlignType[] = [];
  for (
    let token = tokenStart;
    tokens.kind(token) !== BlockKind.TableRowOpen &&
    tokens.kind(token) !== BlockKind.TableClose;
    token++
  ) {
    const kind = tokens.kind(token);
    result.push(
      kind === BlockKind.TableAlignLeft
        ? "left"
        : kind === BlockKind.TableAlignRight
          ? "right"
          : kind === BlockKind.TableAlignCenter ? "center" : null,
    );
  }
  return result;
}

export const feature: SyntaxFeature = {
  block: {
    fallbacks: [
      (source, lines, tokens, start, contentOffset, context) => {
        const delimiterLine = start + 1;
        if (delimiterLine >= lines.length) {
          return;
        }
        const delimiterOffset = lineIndentOffset(source, lines, delimiterLine);
        if (
          delimiterOffset < 0 ||
          context.startsInterruptingBlock(source, lines, delimiterLine, delimiterOffset)
        ) {
          return;
        }
        const delimiter = delimiterAt(source, lines, delimiterLine, delimiterOffset);
        if (!delimiter) {
          return;
        }
        const header = tableCellsAt(source, lines, start, true, contentOffset);
        if (header?.length !== delimiter.length) {
          return;
        }

        tokens.push(BlockKind.TableOpen, header[0], header[0]);
        emitTableRow(lines, tokens, start, header);
        const delimiterEnd = lines.end(delimiterLine);
        for (let cell = 0; cell < delimiter.length; cell += CellSlot.Stride) {
          tokens.push(
            delimiter[cell + CellSlot.Alignment],
            delimiter[cell],
            delimiter[cell + CellSlot.Stride] ?? delimiterEnd,
          );
        }

        let end = start + 2;
        while (end < lines.length) {
          const contentOffset = lineIndentOffset(source, lines, end);
          if (
            contentOffset < 0 ||
            context.startsInterruptingBlock(source, lines, end, contentOffset)
          ) {
            break;
          }
          const cells = tableCellsAt(source, lines, end, false, contentOffset);
          if (!cells) {
            break;
          }
          emitTableRow(lines, tokens, end, cells);
          end++;
        }
        const tableEnd = lines.end(end - 1);
        tokens.push(BlockKind.TableClose, tableEnd, tableEnd);
        return end;
      },
    ],
    builds: [
      {
        token: BlockKind.TableCellOpen,
        build: buildTableCell,
      },
      {
        token: BlockKind.TableRowOpen,
        build: buildTableRow,
      },
      {
        token: BlockKind.TableOpen,
        build(tokenStart, context) {
          const tokens = context.structure.tokens;
          const close = tokenStart + tokens.nodeLength(tokenStart) - 1;
          const start = context.locator.locationAt(tokens.start(tokenStart));
          // Tables are emitted as a header row, delimiter leaves, then body rows.
          const header = tokenStart + 1;
          const delimiter = header + tokens.nodeLength(header);
          const align = tableAlignment(delimiter, context);
          const rows = buildBlockChildren<TableRow>(tokenStart, context);
          return {
            type: "table",
            align,
            children: rows,
            position: {
              start,
              end: context.locator.locationAt(tokens.start(close)),
            },
          };
        },
      },
    ],
  },
};

import { Character } from "../../constants/character.ts";
import { InlineKind } from "../../constants/inline.ts";
import {
  appendInlineToken,
  inlineTokenData,
  inlineTokenEnd,
  inlineTokenStart,
} from "../../inline/tokens.ts";
import type { SyntaxFeature } from "../types.ts";
import type { Attributes } from "./attributes/types.ts";

export const feature: SyntaxFeature = {
  inline: {
    scans: [
      {
        marker: Character.LeftCurlyBracket,
        scan(source, start, tokens) {
          if (source.charCodeAt(start + 1) !== Character.LeftCurlyBracket) {
            return -1;
          }
          const close = source.indexOf("}}", start + 2);
          if (close < 0) {
            return -1;
          }
          const separator = source.indexOf("||", start + 2);
          const valueEnd = separator < 0 || separator > close ? close : separator;
          if (!source.slice(start + 2, valueEnd).trim()) {
            return -1;
          }
          const end = close + 2;
          appendInlineToken(tokens, InlineKind.Binding, start, end, valueEnd - start);
          return end;
        },
      },
    ],
    builds: [
      {
        kind: "leaf",
        token: InlineKind.Binding,
        build(tokenIndex, position, context) {
          const source = context.view.text;
          const tokenStart = inlineTokenStart(context.tokens, tokenIndex);
          const start = tokenStart + 2;
          const end = inlineTokenEnd(context.tokens, tokenIndex) - 2;
          const separator = tokenStart + inlineTokenData(context.tokens, tokenIndex);
          const value = source.slice(start, separator).trim();
          const defaultValue = separator === end ? "" : source.slice(separator + 2, end).trim();
          const attributes: Attributes = { ":value": value };
          if (defaultValue) {
            attributes.defaultValue = defaultValue;
          }
          return {
            type: "inlineComponent",
            name: "binding",
            attributes,
            children: [],
            position,
          };
        },
      },
    ],
  },
};

import { BlockKind } from "../../constants/block.ts";
import { Character } from "../../constants/character.ts";
import { InlineKind } from "../../constants/inline.ts";
import { leafBlockPosition } from "../../fragment/block.ts";
import { inlineTokenData } from "../../inline/tokens.ts";
import type { BlockLines } from "../../block/lines.ts";
import type { SyntaxFeature } from "../types.ts";

export function isThematicBreak(
  source: string,
  lines: BlockLines,
  index: number,
  contentOffset: number,
): boolean {
  const marker = source.charCodeAt(contentOffset);
  if (
    marker !== Character.Asterisk &&
    marker !== Character.HyphenMinus &&
    marker !== Character.LowLine
  ) {
    return false;
  }
  let count = 0;
  for (let offset = contentOffset, end = lines.end(index); offset < end; offset++) {
    const code = source.charCodeAt(offset);
    if (code === marker) {
      count++;
    }
    else if (code !== Character.Space && code !== Character.CharacterTabulation) {
      return false;
    }
  }
  return count >= 3;
}

export const feature: SyntaxFeature = {
  block: {
    builds: [
      {
        token: BlockKind.ThematicBreak,
        build(tokenStart, context) {
          return {
            type: "thematicBreak",
            position: leafBlockPosition(tokenStart, context),
          };
        },
      },
    ],
    starts: [
      {
        codes: [
          Character.Asterisk,
          Character.HyphenMinus,
          Character.LowLine,
        ],
        interrupt(source, lines, index, contentOffset) {
          return isThematicBreak(source, lines, index, contentOffset);
        },
        start(source, lines, tokens, start, contentOffset) {
          if (!isThematicBreak(source, lines, start, contentOffset)) {
            return;
          }
          tokens.push(BlockKind.ThematicBreak, contentOffset, lines.end(start));
          return start + 1;
        },
      },
    ],
  },
  inline: {
    builds: [
      {
        kind: "leaf",
        token: InlineKind.HardBreak,
        build(tokenIndex, position, context) {
          const lineStart = inlineTokenData(context.tokens, tokenIndex);
          return {
            type: "break",
            position: {
              start: position.start,
              end: context.locator.locationAt(context.view.mapOffset(lineStart - 1) + 1),
            },
          };
        },
      },
    ],
  },
};

