import { strict as assert } from "node:assert";
import { execFileSync } from "node:child_process";
import { createHash } from "node:crypto";
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { cpus } from "node:os";
import { resolve } from "node:path";
import { pathToFileURL } from "node:url";
import { load } from "../test/benchmark/helpers/corpus.ts";

// Diagnostics and correctness only. Use benchmark-abba.ts for uninstrumented timing.
const [command, directory, variant = "baseline"] = process.argv.slice(2);
assert.ok(directory, "Usage: node scripts/fence-research.mjs prepare|validate|count|diagnose|summarize OUTPUT [VARIANT]");
const root = resolve(import.meta.dirname, "..");
const output = resolve(directory);
const fencePath = "packages/satorigear/src/block/fence.ts";
const variants = ["baseline", "minimum", "deferred", "bounded", "suffix", "indent", "lastIndex"];
const features = { footnote: true, frontmatter: true, math: true, strikethrough: true, table: true, taskList: true, component: true, attributes: true };
const hash = (text) => createHash("sha256").update(text).digest("hex");
const save = (name, value) => writeFileSync(resolve(output, name), JSON.stringify(value, null, 2) + "\n");
const bundle = (name) => resolve(output, name, "index.mjs");
const importVariant = (name) => import(pathToFileURL(bundle(name)).href);
const replace = (text, before, after) => {
  assert.equal(text.split(before).length, 2, `Expected one occurrence: ${before}`);
  return text.replace(before, after);
};

function candidate(source, name) {
  if (name === "baseline") {
    return source;
  }
  if (name === "lastIndex") {
    // A successful prefix is guaranteed by the first-marker proof. On failure,
    // sticky matching resets lastIndex to zero, below this nonempty row's end.
    return replace(source, "  return closing.test(source) && closing.lastIndex === lineEnd;", "  closing.test(source);\n  return closing.lastIndex === lineEnd;");
  }
  if (name === "minimum") {
    // A static rule minimum becomes an Irregexp fact; the dynamic opening length
    // still needs the existing probe. No per-opening compilation or cache.
    return replace(source, "}+[ \\t]*`,", `}{\${rule.minimumLength},}[ \\t]*\`,`);
  }
  if (name === "suffix") {
    // Reuse the first-marker proof instead of making Irregexp validate it again.
    return replace(replace(source, "}+[ \\t]*`,", "}*[ \\t]*`,"), "  closing.lastIndex = offset;", "  closing.lastIndex = offset + 1;");
  }
  if (name === "indent") {
    return replace(source, `    const contentOffset = lineIndentOffset(source, lines, index);
    if (contentOffset < 0 || source.charCodeAt(contentOffset) !== fence.marker) {
      return false;
    }
    offset = contentOffset;`, `    // The first space is proven; inspect the remaining indentation only once.
    const lineEnd = lines.end(index);
    const limit = lineStart + 3 - lines.prefixColumns(index);
    offset++;
    while (offset < lineEnd && offset < limit && source.charCodeAt(offset) === Character.Space) {
      offset++;
    }
    if (offset > limit || offset === lineEnd || source.charCodeAt(offset) !== fence.marker) {
      return false;
    }`);
  }
  if (name === "deferred") {
    const start = source.indexOf("  const lineEnd = lines.end(index);", source.indexOf("export function closesFence"));
    const end = source.indexOf("\n}", start);
    return source.slice(0, start) + `  const closing = fence.closingPattern;
  closing.lastIndex = offset;
  if (!closing.test(source)) {
    return false;
  }
  const lineEnd = lines.end(index);
  const lastRequired = offset + fence.length - 1;
  return closing.lastIndex === lineEnd && lastRequired < lineEnd &&
    source.charCodeAt(lastRequired) === fence.marker;` + source.slice(end);
  }
  assert.equal(name, "bounded");
  const start = source.indexOf("  const closing = fence.closingPattern;", source.indexOf("export function closesFence"));
  const end = source.indexOf("\n}", start);
  return source.slice(0, start) + `  // The first marker is already proven; keep every subsequent read in this row.
  offset++;
  while (offset < lineEnd && source.charCodeAt(offset) === fence.marker) {
    offset++;
  }
  return offset > lastRequired && trimLineWhitespaceStart(source, offset, lineEnd) === lineEnd;` + source.slice(end);
}

async function buildSnapshot(name, sources) {
  const { build } = await import("tsdown");
  await build({
    config: false,
    cwd: resolve(root, "packages/satorigear"),
    entry: ["src/index.ts"],
    tsconfig: resolve(root, "tsconfig.json"),
    dts: false,
    exports: false,
    sourcemap: true,
    outDir: resolve(output, name),
    outputOptions: { comments: false },
    plugins: [{
      name: "frozen-fence-research",
      load(id) {
        return sources[id.replace(root + "/", "")];
      },
    }],
  });
}

if (command === "prepare") {
  mkdirSync(output, { recursive: true });
  const snapshot = resolve(output, "sources.json");
  const sources = existsSync(snapshot) ? JSON.parse(readFileSync(snapshot, "utf8")) : Object.fromEntries(
    execFileSync("rg", ["--files", "packages/satorigear/src"], { cwd: root, encoding: "utf8" }).trim().split("\n")
      .map((path) => [path, readFileSync(resolve(root, path), "utf8")]),
  );
  if (!existsSync(snapshot)) {
    save("sources.json", sources);
  }
  const meta = { runtime: process.version, v8: process.versions.v8, cpu: cpus()[0].model, arch: process.arch, head: execFileSync("git", ["rev-parse", "HEAD"], { cwd: root, encoding: "utf8" }).trim(), sourceHashes: Object.fromEntries(Object.entries(sources).map(([path, source]) => [path, hash(source)])), variants: {} };
  for (const name of variants) {
    const text = candidate(sources[fencePath], name);
    writeFileSync(resolve(output, `${name}-fence.ts`), text);
    await buildSnapshot(name, { ...sources, [fencePath]: text });
    meta.variants[name] = { fenceHash: hash(text), bundleHash: hash(readFileSync(bundle(name))) };
  }
  save("metadata.json", meta);
}
else if (command === "validate") {
  const baseline = await importVariant("baseline");
  const names = process.argv[4] ? [variant] : variants.filter((name) => name !== "baseline");
  const modules = await Promise.all(names.map(importVariant));
  const results = {};
  for (let index = 0; index < names.length; index++) {
    const actual = modules[index].createParser({ features });
    const expected = baseline.createParser({ features });
    let documents = 0; let edits = 0;
    const check = (source, edit) => {
      assert.deepEqual(actual.parse(source), expected.parse(source), JSON.stringify(source));
      documents++;
      if (!edit) {
        return;
      }
      const a = actual.createDocument(source); const b = expected.createDocument(source);
      for (const change of [edit, { start: edit.start, end: edit.start + edit.text.length, text: source.slice(edit.start, edit.end) }]) {
        a.edit([change]); b.edit([change]);
        assert.deepEqual(a.tree, b.tree);
        assert.deepEqual(a.tree, actual.parse(a.source));
        edits++;
      }
    };
    for (const corpus of load()) {
      for (const original of corpus.documents) {
        for (const ending of ["\n", "\r", "\r\n", "mixed"]) {
          let row = 0;
          check(original.replace(/\r\n|\r|\n/g, () => (ending === "mixed" ? ["\n", "\r", "\r\n"][row++ % 3] : ending)));
        }
      }
    }
    for (const marker of ["`", "~", "$"]) {
      for (const length of [2, 3, 4, 8, 32, 257]) {
        for (const prefix of ["", " ", "   ", "    ", "\t", "> ", "- ", "> - "]) {
          for (const tail of ["", " ", "\t", "x", "\u2028", "\u2029", "\0", " " + marker]) {
            for (const delta of [-1, 0, 1]) {
              const open = marker.repeat(length); const close = marker.repeat(length + delta);
              const ending = ["\n", "\r", "\r\n"][delta + 1];
              const source = [prefix + open, prefix + "body 中😀", prefix + close + tail, prefix + "after", ""].join(ending);
              const position = source.indexOf(close + tail, source.indexOf("body"));
              check(source, { start: position, end: position + 1, text: "x" });
            }
          }
        }
      }
    }
    // A required-position probe alone cannot prove the intervening run.
    for (const marker of ["`", "~", "$"]) {
      for (const body of [marker + " " + marker, marker + "x" + marker, marker + "\t" + marker, marker.repeat(2) + " " + marker]) {
        check(`${marker.repeat(3)}\n${body}\nafter\n${marker.repeat(3)}\n`);
      }
    }
    results[names[index]] = { documents, edits, completeAstAndPositions: true };
  }
  const csp = process.execArgv.includes("--disallow-code-generation-from-strings") ? "-csp" : "";
  save(`validation${csp}${process.argv[4] ? "-" + variant : ""}.json`, results);
  console.log(results);
}
else if (command === "count") {
  let text = readFileSync(bundle("baseline"), "utf8");
  text = replace(text, "function fenceAt(source, lines, index, rule, markerOffset) {", "function fenceAt(source, lines, index, rule, markerOffset) {\n globalThis.__fenceOpening(source, lines, index, rule, markerOffset);");
  text = replace(text, "function closesFence(source, lines, index, fence) {", "function closesFence(source, lines, index, fence) {\n globalThis.__fenceClosing(source, lines, index, fence);");
  const counted = resolve(output, "counted.mjs");
  writeFileSync(counted, text);
  const { createParser } = await import(pathToFileURL(counted).href);
  const baseline = await importVariant("baseline");
  let stats;
  const bump = (object, key) => {
    object[key] = (object[key] ?? 0) + 1;
  };
  globalThis.__fenceOpening = (source, lines, index, rule, offset) => {
    stats.open.calls++;
    const marker = source.charCodeAt(offset);
    if (marker !== rule.marker && marker !== rule.alternateMarker) {
      stats.open.rejectMarker++; return;
    }
    let end = offset + 1;
    while (source.charCodeAt(end) === marker) {
      end++; stats.open.runUnits++;
    }
    if (end - offset < rule.minimumLength) {
      stats.open.rejectLength++; return;
    }
    if (marker === rule.forbiddenInfoMarker) {
      stats.open.forbiddenScans++;
      while (end < lines.end(index)) {
        stats.open.infoUnits++;
        if (source.charCodeAt(end++) === marker) {
          stats.open.rejectInfo++; return;
        }
      }
    }
    stats.open.accepted++;
  };
  globalThis.__fenceClosing = (source, lines, index, fence) => {
    const s = stats.close;
    s.calls++;
    let offset = lines.start(index);
    const first = source.charCodeAt(offset);
    if (first !== fence.marker && first !== 32) {
      s.rejectFirst++; return;
    }
    if (first !== fence.marker) {
      const limit = offset + 3 - lines.prefixColumns(index); const end = lines.end(index);
      while (offset < end && offset < limit && source.charCodeAt(offset) === 32) {
        offset++;
      }
      if (offset > limit || offset === end || source.charCodeAt(offset) !== fence.marker) {
        s.rejectIndent++; return;
      }
    }
    s.candidates++;
    bump(s.requiredLength, fence.length);
    const end = lines.end(index); const last = offset + fence.length - 1;
    if (last >= end) {
      s.rejectBounds++; return;
    }
    if (source.charCodeAt(last) !== fence.marker) {
      s.rejectProbe++; return;
    }
    s.regexp++;
