      const end = tail.search(/\n(?:\[|kind = REGEXP|--- Raw source ---|FENCE_PHASE|RelocInfo)/);
      return tail.slice(0, end < 0 ? tail.length : end);
    });
    const phases = log.split("FENCE_PHASE ").slice(1).map((text) => ({
      phase: text.split("\n")[0],
      bailouts: text.split("bailout (").length - 1,
      compilationEvents: text.split("\n").filter((line) => /completed compiling|completed optimizing/.test(line)),
    }));
    report.machine[name] = { source: readFileSync(resolve(output, `${name}-fence.ts`), "utf8"), optimized, regexps, phases, logHash: hash(log), inlining: log.split("\n").filter((line) => /Inlining .*closesFence/.test(line)) };
