    jsBytes: optimized.map((text) => Number(text.match(/Instructions \(size = (\d+)\)/)[1])),
    regexpBytes: regexps.map((text) => Number(text.match(/Instructions \(size = (\d+)\)/)[1])),
  }])));
}
else {
  throw new Error(`Unknown command: ${command}`);
}

